window.MONSTER_CHUNK_77 = [{"name":"Goliath Spider","cr":11,"xp":12800,"alignment":"N","size":"Colossal","type":"vermin","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":25,"ac_touch":3,"ac_flat_footed":24,"ac_mods":"+1 Dex, +22 natural, -8 size","hp":147,"hd":"14d8+84","hdvalue":14,"fort":15,"ref":5,"will":4,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":40},{"type":"climb","speed":20}],"melee":"bite +17 (6d8+22 plus poison)","space":"30 ft.","reach":"30 ft.","special_attacks":[{"type":"poison"},{"type":"poisoned web","details":"+13 ranged, DC 23, 14 hp"},{"type":"trample","details":"4d8+22, DC 32"}],"strength":41,"dexterity":13,"constitution":22,"wisdom":10,"charisma":2,"baseatk":10,"cmb":33,"cmd":44,"cmd_special":"+12 vs. trip","skills":[{"skill":"Climb","value":23},{"skill":"Perception","value":4},{"skill":"Stealth","value":-7,"special":"+1 in forests"}],"environments":["any forests","any swamps"],"organizations":["solitary","pair","colony (3-6)"],"treasure":"incidental","description_visual":"This massive brown-and-green tarantula is the size of a large house and has huge, razor-sharp fangs.","group":"Spider","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 23; frequency 1/round for 6 rounds; effect 1d6 Str and paralysis 1 round; cure 2 consecutive saves."},{"type":"Poisoned Web","kind":"Ex","details":"This ability works like the web ability, but affects all creatures in a 10-foot-radius burst. In addition, any creature hit by the web must save against the spider's poison."}],"description":"Goliath spiders are giant hunting spiders that most often prey on large creatures such as giant scorpions, snakes, and younger dragons, but sometimes catch and paralyze smaller prey to eat later. Camouflaged by their hairs and coloration, they prowl atop the forest canopy, dropping upon unsuspecting creatures. Females often cannibalize their mates.","ecology":"","habitat_society":""},{"name":"Gongorinan","cr":11,"xp":12800,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","qlippoth","evil","extraplanar"],"init":10,"senses":[{"type":"all-around vision"},{"type":"darkvision","modifier":"60 ft."}],"auras":["horrific appearance (30 ft., DC 20)"],"ac":27,"ac_touch":17,"ac_flat_footed":20,"ac_mods":"+6 Dex, +1 dodge, +10 natural","hp":137,"hd":"11d10+77","hdvalue":11,"fort":14,"ref":13,"will":7,"dr":"10/lawful","immunities":["cold","acid","mind affecting effects","polymorph effects"],"resists":[{"type":"acid","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":22,"speed":[{"type":"land","speed":40},{"type":"climb","speed":40}],"melee":"+1 scimitar +19 (1d6+7/15-20), claw +17 (1d8+6 plus bleed), sting +15 (1d4+3 plus poison), pincer +15 (1d6+3 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bleed","details":"1d6"},{"type":"constrict","details":"1d6+7"},{"type":"oviposition"},{"type":"web","details":"+17 ranged, DC 22, 11 hp"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"},{"spell":"freedom of movement"}]},{"frequency":"at-will","spells":[{"spell":"statue"}]},{"frequency":"1/day","spells":[{"spell":"dimension door"},{"spell":"mass reduce person"},{"spell":"polymorph any object"}]},{"frequency":"3/day","spells":[{"spell":"baleful polymorph"},{"spell":"protection from law"}]}],"strength":23,"dexterity":23,"constitution":24,"intelligence":13,"wisdom":18,"charisma":20,"baseatk":11,"cmb":17,"cmb_special":"+4 vs. grapple","cmd":34,"cmd_special":"+8 vs. trip","feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Critical (scimitar)"},{"feat":"Improved Initiative"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Weapon Focus (scimitar)"}],"skills":[{"skill":"Acrobatics","value":20,"special":"+24 when jumping"},{"skill":"Climb","value":28},{"skill":"Disguise","value":16,"special":"+24 as a boulder while in statue form"},{"skill":"Knowledge (arcana)","value":15},{"skill":"Perception","value":18},{"skill":"Stealth","value":20,"special":"+28 among rocks"},{"skill":"Swim","value":17}],"languages":["Abyssal","telepathy 100 ft."],"environments":["any underground (Abyss)"],"organizations":["solitary","pair","cast (3-10)"],"treasure":"standard (+1 scimitar plus other treasure)","description_visual":"This human-sized crablike creature scuttles on six stumpy legs, and each of its four arms sports a different method of inflicting pain.","group":"Qlippoth","source":"AP 64","special_abilities":[{"type":"Horrific Appearance","kind":"Su","details":"Creatures that succumb to a gongorinan's horrific appearance become confused for 1d4 rounds."},{"type":"Oviposition","kind":"Su","details":"A gongorinan can implant a stony egg the size of a human heart in the body of any Small or larger pinned, helpless, or willing creature as a full-round action that provokes an attack of opportunity. This action deals 1d4 points of Constitution damage to the victim. If the victim survives this damage, the egg takes root deep in the victim's body, links to his mind, and begins gestating. The egg grows rapidly, dealing 1 point of Intelligence drain every day to a minimum score of 1. Once this Intelligence drain affects a creature that already has an effective Intelligence score of 1, the egg \"hatches\" inside of the victim. This causes the victim to immediately transform into a horrid animal, aberration, magical beast, or vermin (the exact choice is made by the gongorinan according to its strange goals and unknowable desires), whereupon it begins living out its new life via pure instinct-this effect otherwise functions as if it were baleful polymorph to which the creature had failed its secondary Will save to retain its personality. A gongorinan can command the actions of a creature that has undergone this transformation as if the victim had been affected by dominate monster (this works even on creatures that are normally immune to such effects as a result of being mindless) as long as the gongorinan is within 120 ft. of the creature. The effect can be reversed by break enchantment (DC 22-treat the gongorinan's Hit Dice as it caster level), but cannot be dispelled."},{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 22; frequency 1/round for 6 rounds; effect 1d3 Strength damage and staggered for 1 round; cure 2 consecutive saves. The save DC is Constitution-based."}],"description":"The gongorinans are the spawn of the nascent qlippoth lord Yamasoth, although one could be forgiven for thinking them of them less as offspring and more as parasites. A gongorinan's basic shape resembles that of an immense, stocky crab, save that they lack all of the features crabs have adapted for an aquatic life-gongorinans are terrestrial creatures. A typical gongorinan possesses no fewer than a dozen stalked eyes, and is capable of extending these eyes from the upper edges of its body just above its mouth to a length of nearly 3 ft., giving it extraordinary vision in all directions. A gongorinan's mouth is a complex tangle of sliding plates and toothy ridges that rasp and shriek against each other as it speaks and chews, but despite their frightening shapes, these mouthparts are ill-suited for making physical attacks; the gongorinan relies upon its arms for that. Each gongorinan has four of these, and each arm is a different, highly specialized appendage. The humanoid arm is used for fine manipulation or the wielding of weaponry, while the mantislike claw is used to shred flesh and create deep, bleeding wounds. The needle-covered tentacle is used to sting and inject a painful poison to stagger foes, while the pincer is used to snatch and hold victims close for oviposition.\n\nA typical gongorinan stands about 6 ft. tall and weighs 800 pounds. When at rest, a gongorinan retracts its limbs into its rock-encrusted body, allowing it to appear remarkably like nothing more than a large, misshapen boulder. Larger specimens known as elder gongorinans exist (and often possess additional and even more dangerous arms), but these are quite rare on the Material Plane save for in the depths of Hollow Mountain.\n\nEcology\n\nAll gongorinans carry within their bodies a brood of horrific egg masses, yet these eggs are not used for the propagation of their kind (that process is governed by a more traditional and yet more nightmarish method best left unspoken). Instead, these eggs carry within their stony shells a raw quintessence of the Abyss, infused with the ichor-seed of the gongorinans' lord, Yamasoth. Whereas most creatures are driven to breed and multiply, the gongorinans are instead driven to seek out humanoid hosts for their eggs. The implantation happens via the gongorinan's mouth and a hideous ovipositor that's not quite tongue and not quite toothed prolapsing throat, but something worse. Fortunately for most who might encounter a gongorinan, the process of oviposition leaves the horrid creature open to attack and cannot be performed quickly, yet to the lone adventurer caught and overwhelmed by a gongorinan, this is small comfort indeed.\n\nOnce an egg has been implanted, it takes many days to grow, and the gongorinan prefers to carry the unfortunate host off to restrain it in a hidden location. Victims are often cocooned in webs or left stranded in high cavern ledges far above the ground so that the egg can gestate. As it grows, the egg feeds on the victim's mind, absorbing the victim's intellect until it has reduced the host to a drooling wreck. At this point, the egg doesn't hatch so much as it merely merges with the host, effecting a horrific and permanent transformation into a monstrous form. The gongorinan can inf luence this ultimate form as it lays its egg. It typically chooses powerful creatures that are already found in the region, for these \"young\" are loyal to their parent and serve as loyal guardians or playthings. Victims retain no true portion of their previous personality, but those who have been rescued from this horrific fate via powerful magic do retain memories of their time as a transformed monstrosity. Many never quite recover from these ordeals, and often develop a peculiar form of madness in which they regard their monstrous life as having been their true life, and their true life as the curse. The most despondent of these victims eventually seek the promise of peace through suicide rather than endure the dreams of their life as a monster-dreams that carry within them a most horrible longing.\n\nHabitat & Society\n\nGongorinans are an industrious and intelligent breed of qlippoth, and where they find themselves, they invariably form hive-like complexes to live in. These gongorinan \"cities\" are labyrinthine affairs with plenty of chambers for their transformed children to live in. In the Abyss, gongorinan hives can grow truly immense, with populations in the thousands, but even the Material Plane is no stranger to gongorinan hive cities. The largest of these hives are thought to be located deep beneath Hollow Mountain, where Runelord Alaznist lured the Polymorph Plague himself, Yamasoth, into dwelling for a time. While Yamasoth has long vacated the Darklands caverns under Hollow Mountain, they bear the name of his spawn- Gongorina-and his spawn dwell there still.","ecology":"All gongorinans carry within their bodies a brood of horrific egg masses, yet these eggs are not used for the propagation of their kind (that process is governed by a more traditional and yet more nightmarish method best left unspoken). Instead, these eggs carry within their stony shells a raw quintessence of the Abyss, infused with the ichor-seed of the gongorinans' lord, Yamasoth. Whereas most creatures are driven to breed and multiply, the gongorinans are instead driven to seek out humanoid hosts for their eggs. The implantation happens via the gongorinan's mouth and a hideous ovipositor that's not quite tongue and not quite toothed prolapsing throat, but something worse. Fortunately for most who might encounter a gongorinan, the process of oviposition leaves the horrid creature open to attack and cannot be performed quickly, yet to the lone adventurer caught and overwhelmed by a gongorinan, this is small comfort indeed.\n\nOnce an egg has been implanted, it takes many days to grow, and the gongorinan prefers to carry the unfortunate host off to restrain it in a hidden location. Victims are often cocooned in webs or left stranded in high cavern ledges far above the ground so that the egg can gestate. As it grows, the egg feeds on the victim's mind, absorbing the victim's intellect until it has reduced the host to a drooling wreck. At this point, the egg doesn't hatch so much as it merely merges with the host, effecting a horrific and permanent transformation into a monstrous form. The gongorinan can inf luence this ultimate form as it lays its egg. It typically chooses powerful creatures that are already found in the region, for these \"young\" are loyal to their parent and serve as loyal guardians or playthings. Victims retain no true portion of their previous personality, but those who have been rescued from this horrific fate via powerful magic do retain memories of their time as a transformed monstrosity. Many never quite recover from these ordeals, and often develop a peculiar form of madness in which they regard their monstrous life as having been their true life, and their true life as the curse. The most despondent of these victims eventually seek the promise of peace through suicide rather than endure the dreams of their life as a monster-dreams that carry within them a most horrible longing.","habitat_society":"Gongorinans are an industrious and intelligent breed of qlippoth, and where they find themselves, they invariably form hive-like complexes to live in. These gongorinan \"cities\" are labyrinthine affairs with plenty of chambers for their transformed children to live in. In the Abyss, gongorinan hives can grow truly immense, with populations in the thousands, but even the Material Plane is no stranger to gongorinan hive cities. The largest of these hives are thought to be located deep beneath Hollow Mountain, where Runelord Alaznist lured the Polymorph Plague himself, Yamasoth, into dwelling for a time. While Yamasoth has long vacated the Darklands caverns under Hollow Mountain, they bear the name of his spawn- Gongorina-and his spawn dwell there still."},{"name":"Graveknight","cr":11,"xp":12800,"race":"Human graveknight","classes":[{"class":"fighter","level":10}],"alignment":"LE","size":"Medium","type":"undead","subtypes":["augmented humanoid"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["sacrilegious aura (30 ft., DC 19)"],"ac":25,"ac_touch":11,"ac_flat_footed":24,"ac_mods":"+10 armor, +1 Dex, +4 natural","hp":139,"hd":"10d10+80","hdvalue":10,"fort":13,"ref":6,"will":6,"save_mods":"+3 vs. fear","defensive_abilities":["bravery +3","channel resistance +4","rejuvenation"],"dr":"10/magic","immunities":["acid","cold","electricity","undead traits"],"sr":22,"speed":[{"type":"land","speed":30}],"melee":"+1 greatsword +25 (2d6+19 plus 2d6 acid)","ranged":"composite longbow +14 (1d8+11/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel destruction"},{"type":"devastating blast","details":"6d6 acid, DC 19"},{"type":"undead mastery","details":"DC 19"},{"type":"weapon training","details":"heavy blades +2, bows +1"}],"strength":27,"dexterity":12,"constitution":10,"intelligence":15,"wisdom":12,"charisma":18,"baseatk":10,"cmb":20,"cmd":29,"feats":[{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Dazzling Display"},{"feat":"Greater Weapon Focus (greatsword)"},{"feat":"Improved Initiative"},{"feat":"Mounted Combat"},{"feat":"Power Attack"},{"feat":"Ride-By Attack"},{"feat":"Shatter Defenses"},{"feat":"Spirited Charge"},{"feat":"Toughness"},{"feat":"Trample"},{"feat":"Unseat"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (greatsword)"},{"feat":"Weapon Specialization (greatsword)"}],"skills":[{"skill":"Climb","value":13},{"skill":"Intimidate","value":25},{"skill":"Knowledge (nobility)","value":12},{"skill":"Perception","value":19},{"skill":"Ride","value":19},{"skill":"Swim","value":13}],"languages":["Common","Dwarven","Infernal"],"sq":[{"type":"armor training","details":"2"},{"type":"phantom mount"},{"type":"ruinous revivification"}],"environments":["any land"],"organizations":["solitary","troop (graveknight plus 12-24 skeletal champions)"],"treasure":"none","description_visual":"Shadows veil what lurks within the dark, imposing armor of this figure, though two piercing eyes gaze from its closed visor.","source":"PFRPG Bestiary 3","description":"Undying tyrants and eternal champions of the undead, graveknights arise from the corpses of the most nefarious warlords and disgraced heroes-villains too merciless to submit to the shackles of death. They bear the same weapons and regalia they did in life, though warped or empowered by their profane resurrection. The legions they once held also flock to them in death, ready to serve their wicked ambitions once more. A graveknight's essence is fundamentally tied to its armor, the bloodstained trappings of its battle lust. This armor becomes an icon of its perverse natures, transforming into a monstrous second skin over the husk of desiccated flesh and scarred bone locked within.","ecology":"","habitat_society":"","gear":"+1 full plate, +1 greatsword, composite longbow [+8 Str] with 20 arrows, belt of giant strength +2"},{"name":"Greater Verduous Ooze","cr":11,"xp":12800,"race":"ooze","alignment":"N","size":"Large","type":"ooze","init":-5,"senses":[{"type":"blindsight","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"auras":["sleep (60 ft., DC 24)"],"ac":6,"ac_touch":4,"ac_flat_footed":6,"ac_mods":"-5 Dex, +2 natural armor, -1 size","hp":175,"hd":"15d8+54","hdvalue":15,"fort":13,"ref":0,"will":0,"defensive_abilities":["split"],"immunities":["acid","fire","mind-affecting effects","ooze traits","slashing and piercing damage"],"speed":[{"type":"land","speed":40}],"melee":"slam +17 (1d8+10 plus 1d8 acid and grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"acid"},{"type":"constrict","details":"1d8+10 plus 1d8 acid"},{"type":"enliven"}],"strength":24,"dexterity":1,"constitution":26,"wisdom":1,"charisma":1,"baseatk":11,"cmb":19,"cmb_special":"+4 vs. grapple","cmd":24,"cmd_special":"can't be tripped","skills":[{"skill":"Stealth","value":-8,"special":"+12 in forest and plains areas"}],"environments":["temperate forests","temperate plains"],"organizations":["solitary"],"treasure":"none","description_visual":"A pool of greenish muck, blossoming with weird vegetable-like growths and sap-seeping boils, twitches into unnatural motion as a pseudopod springs outward, dragging the entire grotesque mass forward with an ameboid life.","group":"Greater Verdurous Ooze","source":"AP 35","special_abilities":[{"type":"Acid","kind":"Ex","details":": A verdurous ooze secretes a digestive acid that dissolves flesh and metal quickly. Each time a creature takes damage from the ooze's acid, its metal equipment and armor take the same amount of damage from the acid. A DC 25 Reflex save prevents damage to such items. A metal or natural weapon that strikes a greater verdurous ooze takes 1d8 points of acid damage unless the weapon's wielder succeeds on a DC 25 Reflex save. If a greater verdurous ooze remains in contact with a metal object for 1 full round, it inflicts 25 points of acid damage (no save) on the object. The save DCs are Constitution-based."}],"description":"Verdurous oozes are animate masses of protoplasm of a sickly green hue. At rest, their flat bodies stand roughly 5 inches tall and can stretch out to a wide diameter, their surfaces blossoming into what look like thick tangles of mossy roots and gnarled vegetation as they lie still. Known to emit invisible but dangerous chemicals, these masses of slinking muck cause nearby plants to writhe and coil as if alive, while shocking animals into a temporary but deathly torpor. As such, they rarely must hunt to find food, instead sensing passing creatures and preying upon them after they succumb to the oozes' sleep aura. Always ravenous, the powerful acids that comprise these oozes quickly dissolve the flesh of their meals. A verdurous ooze typically weighs 300 pounds and can easily spread to fill a 5-foot-square area. While moving, such crawling muck rises only a few inches tall, though its structure might grow and boil up to a height of 2 or 3 ft. if let undisturbed for a matter of days. Spontaneously grown structures collapse and melt back into the ooze's body as soon as it begins moving again. Ecology Verdurous oozes settle in locations with abundant food, rarely moving far except to feed upon comatose prey that has come too close or to reproduce. Verdurous oozes primarily gain sustenance from the small birds, mammals, and insects that fall prey to their sleep aura, but also prove well suited to devouring larger creatures that fall asleep nearby. Every 2 or 3 years, verdurous oozes collect deep in forests and swamps, clustering in secluded locales tainted by reeking natural compost or the escape of natural gases from the land. As many as 10 oozes might gather during one of these grotesque moots. To reproduce, four verdurous oozes merge to become a greater verdurous ooze. Greater oozes are far more active and hungry than their lesser kin, constantly wandering, feeding, and growing. After several months, the greater verdurous ooze splits into 10 to 15 new verdurous oozes. These new verdurous oozes grow to full size within 6 months. Habitat & Society Verdurous oozes primarily live in temperate forests and plains among high grasses or cultivated crops, though they might also be found in warm plains and jungle environments. As mindless creatures, they pay little attention to others of their kind, save when drawn to reproduce. A notable fact about verdurous oozes is that they beneficially impact nearby plant life; their secretions act as a kind of natural fertilizer. Trees, grass, flowers-all flora benefits from the existence of a nearby verdurous ooze. Over time, this can lead to an increase in the fauna in the area, as they seek to enjoy the rich, lush plants that make up their diet and in turn become prey for the stealthy ooze. Thus, another sign that a verdurous ooze is, or has been, in a particular area is the skeletons of animals that it has consumed, which are left behind once the flesh has been absorbed. Resourceful evil humanoids sometimes take advantage of verdurous oozes' relative lassitude and difficultly escaping from simple pits or other containers, trapping them near the entrances to their lairs. In such instances, the oozes' chemical secretions provide an extra defense for those aware of their presence and the dangers of coming too close. Greater Verdurous Ooze Greater verdurous oozes are formed when several green oozes merge together as part of their reproductive process. They are similar in form but much larger, and while still green, exhibit white and red lines that resemble veins running through them. They are even more voracious and dangerous than standard green oozes, as they eat and eat to gain enough mass to reproduce. A greater verdurous ooze typically weighs 2,400 pounds and can easily spread to fill a 10-foot-square area.","ecology":"Verdurous oozes settle in locations with abundant food, rarely moving far except to feed upon comatose prey that has come too close or to reproduce. Verdurous oozes primarily gain sustenance from the small birds, mammals, and insects that fall prey to their sleep aura, but also prove well suited to devouring larger creatures that fall asleep nearby. Every 2 or 3 years, verdurous oozes collect deep in forests and swamps, clustering in secluded locales tainted by reeking natural compost or the escape of natural gases from the land. As many as 10 oozes might gather during one of these grotesque moots. To reproduce, four verdurous oozes merge to become a greater verdurous ooze. Greater oozes are far more active and hungry than their lesser kin, constantly wandering, feeding, and growing. After several months, the greater verdurous ooze splits into 10 to 15 new verdurous oozes. These new verdurous oozes grow to full size within 6 months.","habitat_society":"Verdurous oozes primarily live in temperate forests and plains among high grasses or cultivated crops, though they might also be found in warm plains and jungle environments. As mindless creatures, they pay little attention to others of their kind, save when drawn to reproduce. A notable fact about verdurous oozes is that they beneficially impact nearby plant life; their secretions act as a kind of natural fertilizer. Trees, grass, flowers-all flora benefits from the existence of a nearby verdurous ooze. Over time, this can lead to an increase in the fauna in the area, as they seek to enjoy the rich, lush plants that make up their diet and in turn become prey for the stealthy ooze. Thus, another sign that a verdurous ooze is, or has been, in a particular area is the skeletons of animals that it has consumed, which are left behind once the flesh has been absorbed. Resourceful evil humanoids sometimes take advantage of verdurous oozes' relative lassitude and difficultly escaping from simple pits or other containers, trapping them near the entrances to their lairs. In such instances, the oozes' chemical secretions provide an extra defense for those aware of their presence and the dangers of coming too close. Greater Verdurous Ooze Greater verdurous oozes are formed when several green oozes merge together as part of their reproductive process. They are similar in form but much larger, and while still green, exhibit white and red lines that resemble veins running through them. They are even more voracious and dangerous than standard green oozes, as they eat and eat to gain enough mass to reproduce. A greater verdurous ooze typically weighs 2,400 pounds and can easily spread to fill a 10-foot-square area."},{"name":"Gug Savant","cr":11,"xp":12800,"alignment":"CE","size":"Large","type":"aberration","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":24,"ac_touch":10,"ac_flat_footed":23,"ac_mods":"+1 Dex, +14 natural, -1 size","hp":127,"hd":"15d8+60","hdvalue":15,"fort":9,"ref":6,"will":12,"immunities":["disease","poison"],"speed":[{"type":"land","speed":40},{"type":"climb","speed":20}],"melee":"bite +17 (1d8+7), 4 claws +17 (1d6+7)","space":"10 ft.","reach":"15 ft.","special_attacks":[{"type":"rend","details":"2 claws, 1d6+10"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"invisibility"},{"spell":"spike stones"},{"spell":"transmute rock to mud"},{"spell":"unholy blight"}]}],"strength":25,"dexterity":12,"constitution":18,"intelligence":11,"wisdom":16,"charisma":18,"baseatk":11,"cmb":19,"cmd":30,"feats":[{"feat":"Awesome Blow"},{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Greater Bull Rush"},{"feat":"Improved Bull Rush"},{"feat":"Lunge"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Climb","value":15},{"skill":"Escape Artist","value":13},{"skill":"Knowledge (dungeoneering)","value":13},{"skill":"Perception","value":27},{"skill":"Stealth","value":15},{"skill":"Survival","value":21}],"languages":["Undercommon"],"sq":[{"type":"compression"}],"environments":["any underground"],"organizations":["solitary","pair","camp (1 plus 3-10 gugs)"],"treasure":"standard","description_visual":"This towering menace has a horrible, vertically aligned mouth and arms that split at the elbows into twin clawed hands. The blessings of its evil god have made this specimen more twisted than its lesser bretheren.","source":"PFRPG Bestiary 2","description":"Some bloodthirsty gugs gain awful powers as gifts from their alien patrons. These monsters are known as savants. Some become actual clerics or oracles of their mad gods-strange powers of darkness, insanity, and blood.","ecology":"","habitat_society":""},{"name":"Harionago","cr":11,"xp":12800,"alignment":"NE","size":"Medium","type":"undead","init":9,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":25,"ac_touch":15,"ac_flat_footed":20,"ac_mods":"+5 Dex, +10 natural","hp":147,"hd":"14d8+84","hdvalue":14,"fort":10,"ref":9,"will":12,"defensive_abilities":["channel resistance +2"],"dr":"10/magic","immunities":["undead traits"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +15 (1d6+4/19-20 plus paralysis), 4 hair barbs +12 (1d6+2/19-20 plus bleed)","space":"5 ft.","reach":"5 ft. (10 ft. with hair barbs)","special_attacks":[{"type":"bleed","details":"5"},{"type":"infectious laughter"},{"type":"paralysis","details":"1d4+1 rounds, DC 23"}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"charm monster"},{"spell":"vampiric touch"}]},{"frequency":"3/day","spells":[{"spell":"feather fall"},{"spell":"levitate"},{"spell":"ray of enfeeblement"},{"spell":"unnatural lust"}]}],"strength":19,"dexterity":20,"intelligence":15,"wisdom":17,"charisma":22,"baseatk":10,"cmb":14,"cmd":29,"feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Critical (hair barb)"},{"feat":"Improved Initiative"},{"feat":"Improved Natural Attack (hair barb)"},{"feat":"Multiattack"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":20},{"skill":"Disguise","value":23},{"skill":"Intimidate","value":16},{"skill":"Knowledge (nobility)","value":5},{"skill":"Perception","value":20},{"skill":"Perform (sing)","value":10},{"skill":"Sense Motive","value":20},{"skill":"Stealth","value":22}],"languages":["Common","Elven","Sylvan"],"environments":["any land"],"organizations":["solitary"],"treasure":"standard","description_visual":"This deathly pale beauty's skin is blemished with bruises and cuts, yet a smile shows behind her flowing tangle of hair.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Infectious Laughter","kind":"Su","details":"As a full-round action, a harionago can emit a scornful laugh ringing out in a 60-foot burst. A creature that hears the laughter must succeed at a DC 23 Will saving thrown or be affected as the hideous laughter spell (CL 14th), except that a laughing creature is considered helpless to the harionago. A creature that successfully saves against a harionago's scornful laughter can't be affected by that same harionago's laughter for 24 hours. This is a mind-affecting effect that can be countered with the countersong class feature. Its save DC is Charisma-based."}],"description":"Despite her ragged dress and unkempt appearance, a harionago is a beautiful and graceful creature. She walks the roads at night pretending to be a lost damsel, luring those she encounters close before striking with her paralyzing claws and jagged hair barbs. However, a harionago's most dangerous weapon is her laugh. A resounding cackle of mocking scorn and hateful malice, it compels those around her to join in mocking concert. A harionago is formed when an innocent woman is murdered in some unspeakable fashion. She rises, twisted by the injustice of the crime against her, into an unnatural and bloodthirsty horror that hunts unsuspecting victims while trying to sate an everlasting lust for revenge. Destroying a harionago doesn't always lay her to rest for good. On rare occasions and by mysterious means, a harionago rises again after a year and a day to resume her hunt. She can only rest after she takes her revenge on those who murdered her. If her murderers are already dead when she returns, she will rest only once every member of her murderers' family lines has been slaughtered.","ecology":"","habitat_society":""},{"name":"Hezrou","cr":11,"xp":12800,"alignment":"CE","size":"Large","type":"outsider","subtypes":["aquatic","chaotic","demon","evil","extraplanar"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["stench (DC 24, 10 rounds)"],"ac":25,"ac_touch":9,"ac_flat_footed":25,"ac_mods":"+16 natural, -1 size","hp":145,"hd":"10d10+90","hdvalue":10,"fort":16,"ref":3,"will":9,"dr":"10/good","immunities":["electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10},{"type":"fire","value":10}],"sr":22,"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"bite +17 (4d4+8 plus grab), 2 claws +17 (1d8+8 plus grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"nausea"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":22,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"chaos hammer"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"blasphemy"},{"spell":"summon","details":"level 4, 1 hezrou 35%"}]},{"frequency":"3/day","spells":[{"spell":"gaseous form"}]}],"strength":27,"dexterity":11,"constitution":29,"intelligence":14,"wisdom":14,"charisma":18,"baseatk":10,"cmb":19,"cmb_special":"+4 vs. grapple","cmd":29,"feats":[{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Improved Initiative"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":21},{"skill":"Escape Artist","value":10},{"skill":"Intimidate","value":14},{"skill":"Knowledge (arcana)","value":15},{"skill":"Perception","value":23},{"skill":"Spellcraft","value":15},{"skill":"Stealth","value":9},{"skill":"Swim","value":29}],"languages":["Abyssal","Celestial","Draconic","telepathy 100 ft."],"sq":[{"type":"amphibious"}],"environments":["any swamps (Abyss)"],"organizations":["solitary","gang (2-4)"],"treasure":"standard","description_visual":"This fiend's armored f lesh is scaly and moist. Its large, toothy mouth gapes below a pair of hungry, reptilian eyes.","group":"Demon","source":"PFRPG Bestiary","special_abilities":[{"type":"Nausea","kind":"Ex","details":"The noxious vapors and foul fluids that constantly weep and seethe from a hezrou's body are particularly heinous to those the creature grapples. Each round a creature is grappled by a hezrou, the grappled foe must make a DC 24 Fortitude save to avoid becoming nauseated. A creature nauseated in this manner remains nauseated until he succeeds on a DC 24 Fortitude save, or until a minute has passed during which he isn't grappled by the hezrou, whichever condition comes first. The save DC is Constitution-based."}],"description":"The hezrou dwells in the vast Abyssal swamps, mires, and waterways, equally at home on land and in the water. The presence of a hezrou has an obvious effect on the nearby flora and water, causing plant life to twist and knurl and infusing water with a foul odor and brackish taste—signs much easier to spot on the Material Plane than the Abyss. Long exposure to this corruption can cause vile transformations and hideous deformities. Often, entire backwater communities of deformed mutants owe their twisted countenances not as much to incest and poor breeding as they do to a hezrou's proximity. Although quite intelligent, a hezrou can fairly be said to waste its intellect. They prefer the simple pleasures-slumber, the thrill of torture, the bliss of feasting on a living meal, or the joy of feeling something beautiful breaking and crumbling in a clenched fist. They don't often seek to build empires or lead cults-although few hezrous would turn away prospective minions who came to serve the demon on their own. These monstrous and bestial creatures form from the souls of evil mortals who poisoned themselves, their kin, or their surroundings, such as drug addicts, assassins, and alchemists who cared not how their experiments polluted the environment.","ecology":"","habitat_society":""},{"name":"Impundulu","cr":11,"xp":12800,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["evil","extraplanar","shapechanger"],"init":9,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":25,"ac_touch":15,"ac_flat_footed":20,"ac_mods":"+5 Dex, +10 natural","hp":133,"hd":"14d10+56","hdvalue":14,"fort":13,"ref":14,"will":10,"dr":"10/magic and cold iron","immunities":["electricity"],"resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"sr":22,"speed":[{"type":"land","speed":20,"special":"30 ft. in humanoid form"},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"bite +19 (1d6+4 plus 1d6 bleed and 1d6 electricity), 2 talons +19 (1d4+4 plus 1d6 electricity and grab), 2 hook +13 (1d4+2 plus 1d6 electricity)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bleed","details":"1d6"},{"type":"breath weapon","details":"60-ft. line, 8d6 electricity, Reflex DC 21 half, usable every 1d4 rounds"},{"type":"electrical discharge"}],"spell_like_abilities_caster_level":14,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"call lightning"},{"spell":"charm person"},{"spell":"gust of wind"}]}],"strength":18,"dexterity":21,"constitution":19,"intelligence":15,"wisdom":18,"charisma":20,"baseatk":14,"cmb":18,"cmb_special":"+4 vs. grapple","cmd":33,"feats":[{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (bite)"},{"feat":"Weapon Focus (talons)"}],"skills":[{"skill":"Bluff","value":22},{"skill":"Diplomacy","value":19},{"skill":"Fly","value":9},{"skill":"Intimidate","value":15},{"skill":"Knowledge (arcana)","value":12},{"skill":"Knowledge (nature)","value":12},{"skill":"Knowledge (planes)","value":12},{"skill":"Perception","value":21},{"skill":"Sense Motive","value":21},{"skill":"Spellcraft","value":19},{"skill":"Stealth","value":22}],"languages":["Abyssal","Common","Fey","Infernal","Polyglot","speak with animals","telepathy 100 ft."],"sq":[{"type":"change shape","details":"one humanoid"},{"type":"shaman form"}],"environments":["temperate forests","warm forests"],"organizations":["solitary","pair","flock (2d6)"],"treasure":"standard","description_visual":"A dark shadow moves rapidly across the ground. In the skies high above, silhouetted by the sun, a monstrous, black-feathered avian creature circles. Slowly, a supernatural wind begins to swirl about the creature, and crackling sparks erupt from its body. Screeching wildly, it descends as if falling from the sky, its blood-f lecked wings tipped with cruel curved hooks, and its protruding lower beak scalloped with vicious, jagged barbs.","source":"AP 40","special_abilities":[{"type":"Blood Drain","kind":"Ex","details":"If it grapples a foe, an impundulu drains blood at the end of its turn, dealing Constitution damage."},{"type":"Electrical Discharge","kind":"Su","details":"An impundulu builds substantial electrical charges in its body-electrical charges visibly crackle about its form. If the impundulu hits a creature with two talons in the same round, this charge releases into that creature, dealing 4d6 points of electricity damage (this damage is in addition to the electricity damage from its talon attacks). The target may attempt a DC 21 Fortitude save for half damage. If one or both of the talon attacks is a critical hit, the jolt is so potent that the target is stunned for 1d4 rounds (creatures that are immune to electricity are immune to this stunning effect). The save DC is Constitution-based. Once the creature releases this charge, it cannot use this ability again for 1d4 rounds while it waits for the energy to build again (though this energy buildup doesn't affect the electrical damage from its regular talon attacks). Familiar Service A mortal of 7th level or higher with the Improved Familiar feat can summon an impundulu to serve as her familiar; an impundulu familiar appears as a birdlike imp or quasit, has the normal statistics of an imp or quasit, and loses all of its own abilities except its subtypes, alignment, and damage reduction. If its master is slain, the impundulu seizes its former master's soul, retreats to a hidden place, and consumes the soul, after which it metamorphoses over the next 24 hours into its natural form, regains all of its normal abilities, and becomes free; most aging masters pass on their impundulu familiars to younger family members rather than let the creatures turn on them."},{"type":"Shaman Form","kind":"Su","details":"An impundulu using its change shape special quality can take on one specific humanoid form as if it had the change shape ability. This form usually resembles that of a jungle shaman, except it has claw-like fingernails and its feet end in talons. In this form, it cannot fly or use its breath weapon, electrical discharge, or hook attacks. An impundulu can remain in this form indefinitely. Its natural form is its bird form. If killed, it reverts to its true form. Witchcraft An impundulu serving as a witch's familiar gives its master additional spells known, just like a witch's patron. The master must choose from one of the following patron themes when binding the impundulu, and this choice cannot be changed without dismissing and re-summoning the impundulu: Agility, Elements, or Transformation. These patron spells known are in addition to any granted by the witch's actual patron."}],"description":"The tribesfolk of southern Garund tell tales of a ruthless winged shapeshifter, a bloodthirsty demon and hunter of men. They call this being impundulu, a name that loosely translates to \"lightning-bird\" after its savage avian form. Legend describes this creature as a huge, stork-like bird that rides upon fierce storms and whose dark feathers crackle with lightning. It is believed that an evil shaman summoned the first impundulu and that using an ancient, taboo ritual, the two formed a blood pact. The shaman offered the impundulu the ability to wear his mortal flesh in exchange for mastery over the demon's significant occult powers. As soon as the impundulu seized control of the shaman's body, it broke the pact—however, the ancient ritual bound the fiend to the mortal form, and even after the shaman perished, it could not shed its flesh. Thus despite its own immortality, the impundulu became forever tied to the realm of mortals. For this reason, it is said, the creature continues to forge pacts with mortal spellcasters in the hope that one day it will unbind the secrets of its cursed existence. Ecology Driven by dark and murderous desires, the impundulu stalks the fringes of the Mwangi's civilized areas, seeking out small villages and well-traveled rivers where prey is plentiful. Most of the time, the fiend hunts in its avian form. A hideous thing of similar appearance to a tremendous stork or vulture, it's readily identified by its distinctive long, jagged beak and its slender wings that each bear a hidden, hooked claw. Despite the creature's intelligence, it behaves barbarically and delights in gory slaughter. It precedes physical attacks by conjuring fierce, wrathful blasts of lightning to confuse and injure prey, then swoops in to rend its prey to pieces. In its humanoid form, the impundulu manifests as a strikingly handsome man with glistening, coal-black skin, whose eyes burn a pale, otherworldly green. His legs end in monstrous raptor's talons, and his black fingernails hang long and curved. Using this form, an impundulu can wander through villages, stalking and seducing women with lies and magic, and preying upon them by draining their blood. The creature rarely uses its humanoid form, reserving it for times it wishes to engage in subtle cruelties. Habitat & Society Impundulus remain unknown outside of Garund, and have adapted to life within its pristine and primal jungles. Usually solitary in regard to their own kind, impundulus are rarely encountered apart from the inf luences of evil spellcasters. The association between witch doctors and impundulus is well known throughout the southern continent. The two often form nefarious pacts that bind the beasts for several generations, and the demons frequently outlive their mortal cohorts, collecting their corrupted souls upon their deaths. Those foolish enough to summon an impundulu soon discover the extent of the creatures' guile and violence. Furthermore, many of these wily demons loathe mortals, and turn on their summoners the moment they complete their pacts. Real-World Mythos The impundulu's real-world origins trace back to Xhosa and Zulu tribes of Southern Africa. Tribal folklore describes the beast as a great bird whose wings crackle with lightning. Tales depict it as a shape-shifting vampire able to take the form of a beautiful man in order to seduce its victims. Most consider the impundulu to be an otherworldly demon, though others believe it to be a supernatural creature which hatches from eggs buried in lightning-struck soil. It is oft depicted as the summoned familiar of a powerful witch-man who commands it to plague victims with illness or commit violent, evil acts.","ecology":"Driven by dark and murderous desires, the impundulu stalks the fringes of the Mwangi's civilized areas, seeking out small villages and well-traveled rivers where prey is plentiful. Most of the time, the fiend hunts in its avian form. A hideous thing of similar appearance to a tremendous stork or vulture, it's readily identified by its distinctive long, jagged beak and its slender wings that each bear a hidden, hooked claw. Despite the creature's intelligence, it behaves barbarically and delights in gory slaughter. It precedes physical attacks by conjuring fierce, wrathful blasts of lightning to confuse and injure prey, then swoops in to rend its prey to pieces. In its humanoid form, the impundulu manifests as a strikingly handsome man with glistening, coal-black skin, whose eyes burn a pale, otherworldly green. His legs end in monstrous raptor's talons, and his black fingernails hang long and curved. Using this form, an impundulu can wander through villages, stalking and seducing women with lies and magic, and preying upon them by draining their blood. The creature rarely uses its humanoid form, reserving it for times it wishes to engage in subtle cruelties.","habitat_society":"Impundulus remain unknown outside of Garund, and have adapted to life within its pristine and primal jungles. Usually solitary in regard to their own kind, impundulus are rarely encountered apart from the inf luences of evil spellcasters. The association between witch doctors and impundulus is well known throughout the southern continent. The two often form nefarious pacts that bind the beasts for several generations, and the demons frequently outlive their mortal cohorts, collecting their corrupted souls upon their deaths. Those foolish enough to summon an impundulu soon discover the extent of the creatures' guile and violence. Furthermore, many of these wily demons loathe mortals, and turn on their summoners the moment they complete their pacts. Real-World Mythos The impundulu's real-world origins trace back to Xhosa and Zulu tribes of Southern Africa. Tribal folklore describes the beast as a great bird whose wings crackle with lightning. Tales depict it as a shape-shifting vampire able to take the form of a beautiful man in order to seduce its victims. Most consider the impundulu to be an otherworldly demon, though others believe it to be a supernatural creature which hatches from eggs buried in lightning-struck soil. It is oft depicted as the summoned familiar of a powerful witch-man who commands it to plague victims with illness or commit violent, evil acts."},{"name":"Inverted Giant","cr":11,"xp":12800,"alignment":"CE","size":"Huge","type":"humanoid","subtypes":["giant"],"init":6,"senses":[{"type":"blindsight","modifier":"60 ft."}],"auras":["fear aura (60 ft., DC 21)"],"ac":25,"ac_touch":10,"ac_flat_footed":23,"ac_mods":"+2 Dex, +15 natural, -2 size","hp":152,"hd":"16d8+80","hdvalue":16,"hp_mods":["fast healing 4"],"fort":15,"ref":7,"will":7,"defensive_abilities":["rock catching"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":30}],"melee":"bite +19 (2d8+9 plus grab), 2 claws +19 (1d8+9 plus 1d6 energy)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"grab","details":"Large"},{"type":"rock throwing","details":"120 ft."},{"type":"runes"},{"type":"swallow whole","details":"2d8+13 bludgeoning damage, AC 17, 15 hp"}],"strength":29,"dexterity":14,"constitution":20,"intelligence":9,"wisdom":11,"charisma":16,"baseatk":12,"cmb":23,"cmb_special":"+4 vs. grapple","cmd":35,"feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Critical Focus"},{"feat":"Improved Bull Rush"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Climb","value":17},{"skill":"Intimidate","value":11},{"skill":"Perception","value":9}],"languages":["Giant","Thassilonian (can't speak)"],"environments":["any"],"organizations":["solitary"],"treasure":"standard","source":"Lost Kingdoms","special_abilities":[{"type":"Claws","kind":"Ex","details":"An inverted giant can channel arcane energy into its fists whenever it makes a successful claw attack, dealing 1d6 points of energy damage (cold, electricity, or fire, chosen when the inverted giant attacks) in addition to the damage its claws normally deal."},{"type":"Runes","kind":"Ex","details":"Whenever a rune giant is affected by a spell or spell-like ability, it can cause the runes covering its body to flash with light. All creatures within 10 ft. of the giant must make a DC 21 Fortitude save or be blinded for 1 round. The saving throw is Charisma-based."}],"description":"Perhaps one of the most disturbing of the runelords' creations was the inverted giant, a hideous monstrosity created when a runelord was displeased with a particular giant minion. Through despicable arcana long lost to the ages, giants were ritually bound and transformed so that they would continue to live and think, but only as monstrous caricatures of themselves, their bodies turned inside out in the most painful and gruesome of punishments. Needless to say, few inverted giants tried their masters' patience again, and the unimaginable pain they suffered throughout the rest of their days served as a maddening punishment that would remind them of their insolence until their merciful deaths.\n\nBefore the Starstone fell and obliterated Thassilon, many of the runelords and their servants enchanted their inverted giant minions, freezing the tormented creatures in stasis so that centuries later they would continue to protect their masters' holdings, their mutilated organs providing sensory information among cunningly-looped entrails and viscera preserved by rune magic. Those who find themselves exploring Thassilonian dungeons and ruins sometimes stumble upon such horrors, inadvertently releasing the monsters and restoring them to raging life and madness, the pain of their mutilated bodies having long since driven them to insanity and burning hatred.\n\nNo two inverted giants look the same, though some features remain fairly consistent between them. Instead of a head, most possess little more than a gaping maw the size of their neck, jagged bones and bits of skull serving as teeth for a monstrous mouth. They have no true eyes-what oracular systems they once had are now embedded somewhere near their sternums-but instead possess an innate sense of direction, and through the dark arcana that surges through their beings they can sense the location of their prey perfectly. Their moist, splotched bodies are marked with runes, and their muscles and bones are often visible through their translucent flesh.\n\nInverted giants understand speech, but their deformed mouths rarely work well enough for them to be understood by others. The average inverted giant is over 20 ft. tall and weighs 1,400 pounds.","ecology":"","habitat_society":""},{"name":"Iron Rhinoceros","cr":11,"xp":12800,"alignment":"N","size":"Huge","type":"construct","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":25,"ac_touch":9,"ac_flat_footed":24,"ac_mods":"+1 Dex, +16 natural, -2 size","hp":131,"hd":"14d10+54","hdvalue":14,"fort":6,"ref":7,"will":4,"dr":"10/adamantine","immunities":["construct traits","fire"],"speed":[{"type":"land","speed":40}],"melee":"gore +21 (3d8+9/19-20), 2 chains +19 (2d6+4 plus grab)","space":"15 ft.","reach":"10 ft. (20 ft. with chains)","special_attacks":[{"type":"grasping chains"},{"type":"powerful charge","details":"gore, 6d8+16 or scooping charge"},{"type":"powerful drag"},{"type":"swallow whole","details":"2d6 fire damage, AC 18, 13 hp"},{"type":"trample","details":"2d6+8 plus grasping chains, DC 26"}],"strength":28,"dexterity":12,"intelligence":1,"wisdom":11,"charisma":5,"baseatk":14,"cmb":25,"cmb_special":"+4 vs. grapple","cmd":36,"cmd_special":"+4 vs. trip","feats":[{"feat":"Great Fortitude"},{"feat":"Improved Critical (gore)"},{"feat":"Intimidating Prowess"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Intimidate","value":4},{"skill":"Perception","value":14}],"environments":["any underground","warm mountains"],"organizations":["solitary"],"treasure":"none","description_visual":"Dangling chains cover the riveted iron body of this massive rhinoceros like thick, woolly fur. Its hollow eyes glow-windows into a mighty furnace-and smoke that smells suspiciously like burning flesh billows from its smokestack horns.","source":"AP 95","special_abilities":[{"type":"Grasping Chains","kind":"Ex","details":"An iron rhinoceros is covered in animated chains that grasp at its enemies. It doesn't gain the grappled condition when using its chains to grapple enemies, and can maintain a grapple using its chains as a free action, though doing so prevents it from attacking with that chain. An iron rhinoceros may have up to two creatures grappled in its chains at a time. Additionally, the chains seek to ensnare creatures the rhino tramples. The chains entangle any creature that fails its saving throw against the rhinoceros's trample attack, or that chooses to forgo its save in order to make an attack of opportunity against the rhinoceros. An entangled creature can escape from the chains as a standard action by succeeding on a DC 26 Strength check or a DC 20 Escape Artist check. Each chain has AC 12, hardness 10, and 15 hit points. Creatures entangled in the chains can't move farther than 20 ft. away from the rhinoceros. If the rhinoceros moves farther than 20 ft. from an entangled target, the tethering chain breaks, but the target remains entangled."},{"type":"Powerful Drag","kind":"Ex","details":"An iron rhinoceros can use the drag combat maneuver to savagely scrape its foes across the ground. As a full-round action, an iron rhinoceros can attempt a single drag combat maneuver against every creature currently tethered to its grasping chains. This deals 1d6 points of damage for every 5 ft. dragged, and the chains tethered to any creature more than 20 ft. away break. The dragging damage may increase depending on the terrain, at the GM's discretion. Creatures dragged any distance are knocked prone."},{"type":"Scooping Charge","kind":"Ex","details":"An iron rhinoceros can unhinge its snout in order to scoop enemies into the furnace-like cavity within its belly. When making a powerful charge, the iron rhinoceros can forgo dealing damage in order to gain the grab and fast swallow abilities with its gore attack. The rhinoceros must make this choice at the beginning of its charge."},{"type":"Swallow Whole","kind":"Ex","details":"An iron rhinoceros's belly functions as a furnace, dealing 2d6 points of fire damage to swallowed creatures. Hatches on the rhinoceros's sides allow it to swallow creatures grappled in its chains. In order to take swallowed creatures prisoner without dealing fire damage, the rhinoceros can suppress (or activate) the flames within its furnace as a swift action. When the rhinoceros is suppressing the flames, the furnace instead fills with smoke, forcing swallowed creatures to succeed at a DC 17 Fortitude save each round or be sickened for as long as they remain in the rhinoceros's belly. This save DC is Constitution-based. Creatures attempting to cut their way out of the iron rhinoceros's belly must overcome the durability of the thick furnace walls (hardness 10)."}],"description":"The brutality of fire giants is matched only by their ingenuity at crafting devices of war. Of all their creations, however, few match the ruthless efficiency or raw power of the iron rhinoceros. Built to sate the fire giants' endless desire for slaves, iron rhinoceroses serve as both tireless mounts for giant warlords campaigning against lesser races and as temporary prisons for troublesome captives.\n\nAn iron rhinoceros measures 18 ft. long from snout to tail and stands 12 ft. tall at the shoulder.\n\nEcology\n\nIt is a quirk of fate that fire giants, the most rigid and militaristic of the giant races, created a construct as willful and obstinate as the iron rhinoceros. Early prototypes for the creature borrowed techniques from golem manufacturing and relied on bound elementals to provide the construct's animating force. The results were initially promising, as these unintelligent creatures obeyed without hesitation and executed their orders with mechanical precision. However, they also inherited their golem forebears' tendency to go berserk in battle. Few generals were willing to ride a mount that might turn on its rider, and so these first creations were deemed unreliable and most were broken down for scrap.\n\nFor the second generation of iron rhinoceroses, fire giant blacksmiths bound the spirits of animals rather than elementals into the construct's frame. The results were surprisingly lifelike. When not in use as mounts or engines of war, these new iron rhinoceroses rest and graze as normal rhinoceroses do, even without the need for food or sleep. They \"eat\" combustible materials, such as wood and coal, to fuel their internal furnaces, and seek warm places to\n\nlie down. They also share their living cousins' aggressive tendencies, and attack unfamiliar creatures on sight.\n\nAn iron rhinoceros is only truly loyal to its maker, or to an individual whom its maker designates at the time of its creation. At best, it tolerates the presence of other creatures, and more often displays barely constrained hostility toward its master's servants. An iron rhinoceros prefers not to allow riders other than its master, and such riders take a -4 penalty on Ride checks to control it in battle.\n\nHabitat & Society\n\nIron rhinoceroses are rarely found outside of fire giant camps. Although any sufficiently experienced and equipped spellcaster can create one, something in the mechanical beasts' construction predisposes them to favor giants over other creatures. While they might remain loyal to their creator, iron rhinoceroses display aggression toward any other non-giant creature they meet. These tendencies, combined with the creatures' immense size and strength, make them dangerous to keep in even lightly civilized areas.\n\nAmong some fire giant communities, iron rhinoceroses are a mark of status and power. Many fire giants assume that a general who possesses and commands one has been successful enough at war to afford the exorbitant cost of the beast's creation. Because iron rhinoceroses cannot (or will not) bond with a new master after their creation, elders rarely pass them down along family lines or to successors. Up-and-coming fire giant generals are expected to produce their own iron rhinoceroses to prove their worth as military commanders. In truth, few iron rhinoceroses survive their masters, as both tend to fall in battle against more powerful enemies. On the rare occasion when an iron rhinoceros does outlast its owner, the construct is placed within its master's tomb to serve as a guardian for his body and grave goods. Desperate or foolish young commanders sometimes attempt to steal iron rhinoceroses from the tombs of their ancestors, hoping to gain the prestige that comes with ownership without first proving themselves in war. These young generals more often than not end up impaled, making their attempted theft readily apparent to whatever unfortunate giants must clean up the mess.\n\nConstruction\n\nAn iron rhinoceros is made of 6,000 pounds of forge-hardened iron and steel that costs 5,000 gp.\n\nIRON RHINOCEROS\n\nCL 15th; Price 117,500 gp\n\nConstruction\n\nRequirements Craft Construct, geas/quest, limited wish, resist energy, summon nature's ally V, creator must be caster level 15th; Skill Craft (armor) or Craft (weapons) DC 25; Cost 61,250 gp","ecology":"It is a quirk of fate that fire giants, the most rigid and militaristic of the giant races, created a construct as willful and obstinate as the iron rhinoceros. Early prototypes for the creature borrowed techniques from golem manufacturing and relied on bound elementals to provide the construct's animating force. The results were initially promising, as these unintelligent creatures obeyed without hesitation and executed their orders with mechanical precision. However, they also inherited their golem forebears' tendency to go berserk in battle. Few generals were willing to ride a mount that might turn on its rider, and so these first creations were deemed unreliable and most were broken down for scrap.\n\nFor the second generation of iron rhinoceroses, fire giant blacksmiths bound the spirits of animals rather than elementals into the construct's frame. The results were surprisingly lifelike. When not in use as mounts or engines of war, these new iron rhinoceroses rest and graze as normal rhinoceroses do, even without the need for food or sleep. They \"eat\" combustible materials, such as wood and coal, to fuel their internal furnaces, and seek warm places to\n\nlie down. They also share their living cousins' aggressive tendencies, and attack unfamiliar creatures on sight.\n\nAn iron rhinoceros is only truly loyal to its maker, or to an individual whom its maker designates at the time of its creation. At best, it tolerates the presence of other creatures, and more often displays barely constrained hostility toward its master's servants. An iron rhinoceros prefers not to allow riders other than its master, and such riders take a -4 penalty on Ride checks to control it in battle.","habitat_society":"Iron rhinoceroses are rarely found outside of fire giant camps. Although any sufficiently experienced and equipped spellcaster can create one, something in the mechanical beasts' construction predisposes them to favor giants over other creatures. While they might remain loyal to their creator, iron rhinoceroses display aggression toward any other non-giant creature they meet. These tendencies, combined with the creatures' immense size and strength, make them dangerous to keep in even lightly civilized areas.\n\nAmong some fire giant communities, iron rhinoceroses are a mark of status and power. Many fire giants assume that a general who possesses and commands one has been successful enough at war to afford the exorbitant cost of the beast's creation. Because iron rhinoceroses cannot (or will not) bond with a new master after their creation, elders rarely pass them down along family lines or to successors. Up-and-coming fire giant generals are expected to produce their own iron rhinoceroses to prove their worth as military commanders. In truth, few iron rhinoceroses survive their masters, as both tend to fall in battle against more powerful enemies. On the rare occasion when an iron rhinoceros does outlast its owner, the construct is placed within its master's tomb to serve as a guardian for his body and grave goods. Desperate or foolish young commanders sometimes attempt to steal iron rhinoceroses from the tombs of their ancestors, hoping to gain the prestige that comes with ownership without first proving themselves in war. These young generals more often than not end up impaled, making their attempted theft readily apparent to whatever unfortunate giants must clean up the mess.\n\nConstruction\n\nAn iron rhinoceros is made of 6,000 pounds of forge-hardened iron and steel that costs 5,000 gp.\n\nIRON RHINOCEROS\n\nCL 15th; Price 117,500 gp\n\nConstruction\n\nRequirements Craft Construct, geas/quest, limited wish, resist energy, summon nature's ally V, creator must be caster level 15th; Skill Craft (armor) or Craft (weapons) DC 25; Cost 61,250 gp"},{"name":"Jinmenju","cr":11,"xp":12800,"alignment":"N","size":"Huge","type":"plant","init":3,"senses":[{"type":"all-around vision"},{"type":"blindsense","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["unsettling drone (30 ft., DC 18)"],"ac":25,"ac_touch":7,"ac_flat_footed":25,"ac_mods":"-1 Dex, +18 natural, -2 size","hp":149,"hd":"13d8+91","hdvalue":13,"fort":14,"ref":5,"will":5,"immunities":["plant traits","poison"],"speed":[{"type":"land","speed":10}],"melee":"bite +15 (2d6+8/19-20), 2 slams +16 (1d8+8)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"enticing head-fruits"},{"type":"intoxicating stench"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"share memory","details":"with a range of 55 ft., targeting the jinmenju and 1 creature in range"}]},{"frequency":"3/day","spells":[{"spell":"sculpt sound"},{"spell":"shout"}]}],"strength":27,"dexterity":8,"constitution":22,"intelligence":7,"wisdom":12,"charisma":15,"baseatk":9,"cmb":19,"cmd":28,"feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Lunge"},{"feat":"Toughness"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Perception","value":17}],"languages":["Common"],"environments":["temperate hills","temperate mountains"],"organizations":["solitary"],"treasure":"incidental","description_visual":"A low hum surrounds this huge, gnarled tree. The rotten fruits that hang from its sickly branches look vaguely like human heads.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Enticing Head-Fruits","kind":"Su","details":"Any creature that begins its turn within 5 ft. of a jinmenju must succeed at a DC 22 Will save or be magically compelled to immediately grab a head-fruit and eat it. This is a mind-affecting compulsion effect. A creature that successfully saves is immune to that jinmenju's enticing head-fruits for 24 hours. The save DC is Constitution-based. Anyone who takes a bite out of one suffers from the following effect. Head-Fruit Poison: Head-fruit-ingested; save Fort DC 22; frequency 1/round for 6 rounds; effect 1d3 Wisdom damage and confused for 1 round; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Intoxicating Stench","kind":"Su","details":"Once per day as a swift action, a jinmenju can cause its fruits to emit an unnaturally sweet aroma in a 60-foot spread for 6 rounds. All creatures within the area must succeed at a DC 22 Will save each round or be captivated. A captivated creature takes no actions except to approach the jinmenju via the most direct route possible. If this path leads it into a dangerous area or the jinmenju attacks it, the captivated creature receives a new saving throw. This is a mind-affecting effect. The save DC is Constitution-based."},{"type":"Unsettling Drone","kind":"Su","details":"A jinmenju emits a low, persistent hum that unnerves living creatures that hear it. Those within 30 ft. of it must succeed at a DC 18 Will save or become shaken until they leave the affected area and for 1d4 rounds thereafter. A creature that successfully saves is immune to that jinmenju's unsettling drone for 24 hours. The save DC is Charisma-based."}],"description":"Jinmenjus are trees that grow in hilly regions far from civilized lands, and prey on those who come too close. They are remarkably intelligent and crafty, and use both scent and magical compulsion to lure prey.","ecology":"","habitat_society":""},{"name":"Juggernaut","cr":11,"xp":12800,"alignment":"N","size":"Gargantuan","type":"construct","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":26,"ac_touch":6,"ac_flat_footed":26,"ac_mods":"+20 natural, -4 size","hp":142,"hd":"15d10+60","hdvalue":15,"hp_mods":["fast healing 5"],"fort":5,"ref":5,"will":9,"dr":"10/adamantine","immunities":["construct traits"],"sr":22,"weaknesses":["faith-bound"],"speed":[{"type":"land","speed":30}],"melee":"slam +24 (4d6+19 plus wounding)","space":"20 ft.","reach":"5 ft.","special_attacks":[{"type":"soul-powered"},{"type":"vicious trample","details":"8d6+38 plus wounding, DC 30"}],"spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"enervation"}]}],"strength":36,"dexterity":11,"wisdom":18,"charisma":1,"baseatk":15,"cmb":32,"cmd":42,"cmd_special":"can't be tripped","sq":[{"type":"keyed domains","details":"Death, War"},{"type":"shrine"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This oppressive construct rumbles forth on deadly rollers, crushing everything in its path.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Faith-Bound","kind":"Su","details":"A juggernaut cannot attack any creature that openly wears or displays the holy symbol or unholy symbol of the deity to which the juggernaut is dedicated unless that creature first attacks the juggernaut."},{"type":"Shrine","kind":"Ex","details":"A juggernaut counts as a movable shrine for the deity or religion it is dedicated to."},{"type":"Soul-Powered","kind":"Su","details":"When a juggernaut kills a creature with at least 5 Hit Dice and an alignment two or more steps away from the juggernaut's alignment, it gains a kill point. Add its current total kill points as a bonus on its attack rolls, combat maneuver checks, caster level checks, and skill checks. Add half its current total kill points as a bonus to its natural armor and spell resistance. The juggernaut loses 1 kill point every 24 hours."},{"type":"Vicious Trample","kind":"Ex","details":"A juggernaut's massive rollers deal 8d6+38 points of damage on a successful trample attack."}],"description":"Juggernauts protect locations dedicated to a particular faith, their massive forms infused with divine energy that animates them and infuses them with their deity's power. Some faiths use a juggernaut as a mobile shrine, anointing it with sacred materials and offering prayers to the divine.\n\nKEYED DOMAINS\n\nA juggernaut gain special abilities from two domains granted by the deity to which the juggernaut is dedicated. If an ability requires a saving throw, the save DC is Wisdom-based (DC 19 for most juggernauts). The caster level is equal to the juggernaut's Hit Dice (CL 15th for most juggernauts). The sample juggernaut is keyed to the domains of Death and War-a juggernaut dedicated to some other deity has abilities based on that deity's domains.\n\nAir: Whirlwind (Sp)-The juggernaut can cast whirlwind once per day.\n\nAnimal: Friendly Pack (Sp)-The juggernaut can cast summon nature's ally IV (animals only) three times per day.\n\nArtifice: Repair (Ex)-The juggernaut's fast healing increases to 10.\n\nChaos: Chaotic Attacks (Su)-The juggernaut's slam and vicious trample attacks are treated as chaotic-aligned. Its vicious trample deals an additional 2d6 points of damage to lawful targets.\n\nCharm: Friendship (Sp)-The juggernaut can cast charm monster three times per day. A charmed creature follows the juggernaut and attacks what it attacks.\n\nCommunity: Powerful Allies (Su)-All creatures within 60 ft. of the juggernaut that share the juggernaut's alignment gain a +1 sacred bonus on attack rolls and to AC, and a +2 sacred bonus on saving throws (these are profane bonuses if the juggernaut is evil).\n\nDarkness: Deeper Darkness (Sp)-The juggernaut can cast deeper darkness three times per day.\n\nDeath: Lifesapper (Sp)-The juggernaut can cast enervation three times per day.\n\nDestruction: Destructive Aura (Su)-The juggernaut can emit a 30-foot aura of destruction for 10 rounds per day. All attacks made against targets in the aura (including the juggernaut) gain a +2 morale bonus on damage rolls and all critical threats are automatically confirmed.\n\nEarth: Tremorsense (Su)-The juggernaut gains tremorsense 60 ft.\n\nEvil: Evil Attacks (Su)-The juggernaut's slam and vicious trample attacks are treated as evil-aligned. Its vicious trample deals an additional 2d6 points of damage to good targets.\n\nFire: Flaming Burst (Su)-The juggernaut's slam attack gains the flaming burst weapon special ability. Its vicious trample attack deals an additional 1d6 points of fire damage.\n\nGlory: Grandeur (Su)-The juggernaut inspires all allies within 30 ft., granting them a +2 morale bonus on attack rolls, saving throws, and skill checks.\n\nGood: Good Attacks (Su)-The juggernaut's slam and vicious trample attacks are treated as good-aligned. Its vicious trample deals an additional 2d6 points of damage to evil targets.\n\nHealing: Resurgence (Su)-Five times per day, the juggernaut can remove the dazed, fatigued, shaken, sickened, or staggered condition from an ally within 30 ft.\n\nKnowledge: Absorb Thoughts (Su)-When the juggernaut confirms a critical hit with its slam, the target must succeed at a Will save or take 1d8 points of Intelligence damage.\n\nLaw: Lawful Attacks (Su)-The juggernaut's slam and vicious trample are treated as lawful-aligned. Its vicious trample deals an additional 2d6 points of damage to chaotic targets.\n\nLiberation: Broken Bonds (Su)-10 times per day a standard action, the juggernaut can affect one its allies within 20 ft. with freedom of movement for 1 round.\n\nLuck: Lucky (Su)-Twice per day, the juggernaut may reroll any d20 roll that it has just made before the results of the roll are revealed. The juggernaut must take the result of the reroll, even if it's worse than the original roll.\n\nMadness: Confusion (Sp)-The juggernaut can cast confusion three times per day.\n\nMagic: Resistant (Su)-The juggernaut's SR increases by 5.\n\nNobility: Inspirational (Sp)-The juggernaut can cast good hope three times per day.\n\nPlant: Hedge (Sp)-The juggernaut can cast wall of thorns three times per day.\n\nProtection: Guardian (Su)-The juggernaut and all allies within 30 ft. gain a +2 bonus on all saving throws and a +2 deflection bonus to AC.\n\nRepose: Rest Eternal (Su)-Damage dealt by the juggernaut resists magical healing. Attempting to use such healing to cure this damage requires a successful caster level check against a DC = 11 + the juggernaut's caster level. This ability doesn't affect natural healing or healing provided by extraordinary abilities.\n\nRune: Rune-Carved (Su)-Runes cover the juggernaut. Whenever the juggernaut takes energy damage or energy damage fails to overcome its SR, for the next round, its attacks deal 2d6 points of damage of that energy type. If more than one type of energy attack occurs in a round, roll randomly to determine what kind of extra energy damage it deals.\n\nStrength: Vigorous (Sp)-The juggernaut can cast mass bull's strength once per day.\n\nSun: Sunstrike (Sp)-The juggernaut can cast daylight and searing light three times per day.\n\nTravel: Unstoppable (Su)-The juggernaut ignores penalties for difficult terrain. Its movement increases by 10 ft.\n\nTrickery: Doubles (Sp)-The juggernaut can cast mirror image three times per day.\n\nWar: Bloody (Su)-The juggernaut's slam and vicious trample attacks have the wounding weapon special ability.\n\nWater: Surge (Sp)-The juggernaut can cast hydraulic torrent five times per day.\n\nWeather: Weathermaker (Sp)-The juggernaut can cast control weather once per day.\n\nCONSTRUCTION\n\nA juggernaut's body must be created from 20,000 gp worth of clay, crystal, metal, stone, wood, or bone.\n\nJUGGERNAUT CL 13th; Price 140,000 gp CONSTRUCTION Requirements Craft Construct, greater magic weapon, imbue with spell ability, make whole, stone shape, creator must be caster level 10th; Skill Craft (carpentry, sculptures, or stonemasonry); Cost 80,000 gp","ecology":"","habitat_society":""},{"name":"Juvenile Red Dragon","cr":11,"xp":12800,"alignment":"CE","size":"Large","type":"dragon","subtypes":["fire"],"init":5,"senses":[{"type":"dragon senses"},{"type":"smoke vision"}],"auras":["frightful presence (120 ft., DC 18)"],"ac":29,"ac_touch":10,"ac_flat_footed":28,"ac_mods":"+4 armor, +1 Dex, +15 natural, -1 size","hp":149,"hd":"13d12+65","hdvalue":13,"fort":13,"ref":9,"will":10,"immunities":["fire","paralysis","sleep"],"weaknesses":["vulnerable to cold"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":200,"maneuverability":"poor"}],"melee":"bite +22 (2d6+13), 2 claws +22 (1d8+9), 2 wings +19 (1d6+5), and tail +19 (1d8+13)","space":"10 ft.","reach":"5 ft. (10 ft. with bite)","special_attacks":[{"type":"Breath Weapon","details":"40 ft. cone, DC 21, 8d10 fire"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":18,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect magic"},{"spell":"pyrotechnics"}]}],"spellsknown_caster_level":3,"spellsknown_concentration":8,"spellsknown":[{"spell_level":1,"spell_slots":4,"spells":[{"spell":"mage armor"},{"spell":"ray of enfeeblement"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"flare"},{"spell":"mage hand"},{"spell":"open/close"},{"spell":"prestidigitation"}]}],"strength":27,"dexterity":12,"constitution":21,"intelligence":14,"wisdom":15,"charisma":14,"baseatk":13,"cmb":22,"cmd":33,"cmd_special":"+4 vs. trip","feats":[{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (bite)"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Acrobatics","value":14},{"skill":"Appraise","value":18},{"skill":"Bluff","value":18},{"skill":"Fly","value":15},{"skill":"Intimidate","value":18},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":18},{"skill":"Spellcraft","value":18}],"languages":["Common","Draconic","Giant"],"environments":["warm mountains"],"organizations":["solitary"],"treasure":"triple","description_visual":"A crown of cruel horns surrounds the head of this mighty dragon. Thick scales the color of molten rock cover its long body.","group":"Chromatic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Smoke Vision","kind":"Ex","details":"A very young red dragon can see perfectly in smoky conditions (such as those created by pyrotechnics)."}],"description":"Few creatures are more cruel and fearsome than the mighty red dragon. King of the chromatics, this terrible beast brings ruin and death to the lands that fall under its shadow.","ecology":"","habitat_society":""},{"name":"Larabay","cr":11,"xp":12800,"alignment":"CN","size":"Medium","type":"fey","subtypes":["shapechanger"],"init":10,"senses":[{"type":"low-light vision"}],"ac":25,"ac_touch":17,"ac_flat_footed":18,"ac_mods":"+6 Dex, +1 dodge, +8 natural","hp":144,"hd":"17d6+85","hdvalue":17,"fort":10,"ref":16,"will":13,"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"good"}],"melee":"rapier +15 (1d6+4/18-20 plus mischief)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"befuddling gaze"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"cone of cold"},{"spell":"mirage arcana"}]},{"frequency":"3/day","spells":[{"spell":"hallucinatory terrain"},{"spell":"invisibility"},{"spell":"solid fog"},{"spell":"suggestion"}]},{"frequency":"5/day","spells":[{"spell":"burning hands"},{"spell":"gust of wind"}]}],"strength":18,"dexterity":22,"constitution":21,"intelligence":15,"wisdom":16,"charisma":17,"baseatk":8,"cmb":14,"cmd":29,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Alertness"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (rapier)"}],"skills":[{"skill":"Bluff","value":23},{"skill":"Diplomacy","value":23},{"skill":"Disguise","value":23},{"skill":"Fly","value":30},{"skill":"Knowledge (nature)","value":22},{"skill":"Perception","value":27},{"skill":"Sense Motive","value":27},{"skill":"Stealth","value":26}],"languages":["Common","Polyglot","Sylvan"],"sq":[{"type":"change shape","details":"Medium humanoid; alter self"}],"environments":["temperate coastlines","temperate forests","warm coastlines","warm forests"],"organizations":["solitary","pair","rabble (3-6)"],"treasure":"standard","description_visual":"This pale, blond-haired humanoid possesses bright blue eyes, needlelike teeth, and the large, multicolored wings of a parrot.","source":"Isles Of The Shackles","special_abilities":[{"type":"Befuddling Gaze","kind":"Su","details":"Three times per day as a standard action, a larabay can employ a befuddling gaze attack in a 30-foot cone. Creatures that fail a DC 21 Will save become dazed for 1d4 rounds. Creatures that successfully save are dazzled for 1 round. The save DC is Charisma-based."},{"type":"Mischief","kind":"Su","details":"A larabay can channel its magical energy through whatever one-handed weapon it wields to mystify and disorient foes. Creatures hit by a larabay's weapon must make a DC 21 Will save or take 1 point of Dexterity damage and become confused for 1d6 rounds. The save DC is Charisma-based."}],"description":"Larabays are capricious fey creatures that gravitate toward coastal regions with warm and temperate islands. They are especially fond of toying with sailors and fishermen, playing pranks aboard ships or in seaside towns by assuming various shapes and using their otherworldly powers of mischief. A larabay's idea of fun can quickly become quite serious, however, when its love of trickery begins to outweigh its sympathy for humanity, and a larabay's well-executed joke may result in a potentially fatal situation for those involved. In their never-ending pursuit of a good laugh, larabays have been known to employ their supernatural illusions to draw ships and their crews into precarious situations such as hazardous waters or hidden shoals, and the depredations of a larabay are often only realized after it's too late. On land, larabays entice their unknowing dupes off cliffs' edges, through monster lairs, or into hidden ravines or pools of quicksand.\n\nLarabays use their shapechanging abilities to craft intricate webs of social intrigue, though such schemes are always concocted in an effort simply to conduct a masterful hoax, usually resulting in the devastation or heartbreak of one or more of the parties involved rather than any concrete gains on the fey's part. While larabays have been known to inadvertently perform acts of good in the process of gulling cruel-hearted individuals, their unpredictable and precarious natures make them difficult allies, and one can never be sure just how long a larabay will remain faithful to a particular cause before getting bored or whether its companions are simply its latest victims.","ecology":"","habitat_society":""},{"name":"Living Sandstorm","cr":11,"xp":12800,"alignment":"N","size":"Medium","type":"outsider","subtypes":["earth","elemental"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"sandsight"},{"type":"tremorsense","modifier":"60 ft."}],"ac":26,"ac_touch":17,"ac_flat_footed":19,"ac_mods":"+6 Dex, +1 dodge, +9 natural","hp":147,"hd":"14d10+70","hdvalue":14,"fort":9,"ref":15,"will":12,"dr":"10/-","immunities":["elemental traits"],"speed":[{"type":"land","speed":30},{"type":"burrow","speed":30}],"melee":"2 slams +24 (1d8+10 plus distraction)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"distraction","details":"DC 22"},{"type":"slashing sand"}],"strength":31,"dexterity":22,"constitution":21,"intelligence":12,"wisdom":12,"charisma":13,"baseatk":14,"cmb":24,"cmb_special":"+2 vs. sunder","cmd":41,"cmd_special":"+2 vs. sunder","feats":[{"feat":"Dodge"},{"feat":"Improved Iron Will"},{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Step Up"}],"skills":[{"skill":"Acrobatics","value":20},{"skill":"Fly","value":23},{"skill":"Intimidate","value":18},{"skill":"Knowledge (planes)","value":18},{"skill":"Linguistics","value":4},{"skill":"Perception","value":18},{"skill":"Stealth","value":23,"special":"+31 in sand"},{"skill":"Survival","value":18}],"languages":["Aquan","Auran","Common","Ignan","Terran"],"sq":[{"type":"change shape","details":"humanoid form or sandstorm form; polymorph"},{"type":"compression"}],"environments":["any deserts (Plane of Earth)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This hulking humanoid figure of packed red sand is no taller than an average human, but it is brawny and exceptionally broad.","source":"AP 83","special_abilities":[{"type":"Change Shape","kind":"Su","details":"A living sandstorm can shift between its humanoid form, shaped from packed sand, and a sandstorm form as a standard action. In sandstorm form, a living sandstorm functions as if it were a swarm of Fine creatures with a hive mind, and it loses its burrow speed, slam attacks, and compression abilities, but gains a fly speed and the ability to use its create sand and sand blast abilities. Its Strength score is reduced to 1, but its ability scores are otherwise unchanged. A living sandstorm remains in one form until it chooses to assume its other form. A change in form can't be dispelled, nor does the living sandstorm revert to any particular form when killed (both shapes are its true form). A true seeing spell reveals both forms simultaneously."},{"type":"Sandsight","kind":"Ex","details":"The living sandstorm can see through sand, dust, and other particles in the air as if the air were clear, ignoring the miss chance for these obstructions, up to its normal range of vision."},{"type":"Slashing Sand","kind":"Ex","details":"A living sandstorm's swarm attack deals slashing damage. Its slam attacks deal bludgeoning and slashing damage."}],"description":"Notorious for appearing suddenly out of the roiling tempests of the deep desert, living sandstorms are capable of turning oases and dry farmlands into areas of featureless desert in a shockingly short span of time. When angered, they can scour a whole army down to bits of shining metal and bone buried under ft. of shifting sand over the course of one terrible night. Some Osiriani scholars claim that living sandstorms are related to the deadly khamsin storms that scour the desert, and while these creatures are related to elementals, they have nothing to do with the formation of those iconic storms. Living sandstorms are most comfortable when sand is free to flow across the earth. They become agitated whenever creatures make an effort to remove or limit sand in an area, shelter an area from the drifting dust, or alter the weather to reduce or prevent sandstorms. However, they are curious creatures and enjoy experiencing new interactions with beings of other shapes, and are willing to parley when they believe doing so may open the door to a novel diversion-or if a creature simply appears easy to intimidate.\n\nA living sandstorm in its humanoid shape is about 6 ft. tall and weighs 900 pounds. In sandstorm form, it expands its form into a pulsing cloud of streaming, loose sand, which gathers into small clumps before being reabsorbed into the storm.\n\nEcology\n\nLiving sandstorms are formed from and fed by the unpredictable interaction of raw elemental earth and planar storms or vortices carrying the essence of other planes. These ageless elemental creatures tend to be curious and outgoing when they first discover new places, but are easily frustrated by any kind of restraint. They use their ability to create sand liberally, attempting to pack caves, voids in the Plane of Earth, and other open areas at least half-full of their reddish sand. Because of their origin, they are usually found near gates, portals, and vortices between planes both on the Plane of Earth and on the Material Plane.\n\nHabitat & Society\n\nLiving sandstorms dwell in the rare open caverns on the Plane of Earth. On that plane, they are misfits, feared for their affinities for open spaces and howling winds. When conflicts erupt between the powers of the Elemental Planes, they are sometimes recruited to lead strike teams into other planes, as they are adventurous and enjoy discovering open spaces they can fill with their fine, red sand. They are especially valuable when establishing beachheads on planes that have little in the way of earth, because of their ability to create large amounts of sand in relatively short periods of time.\n\nDue to their intrepidness, they readily answer callings to serve summoners so they can visit new places and spread their sand far and wide. If they see an opportunity to do so, they may break free of their calling and explore the wider Material Plane, where they favor desert climes and their nearby regions, and where they are known to contribute to rapid desertification. When marooned on the Material Plane, they are generally restless until they find a way back to the Plane of Earth, but if they know of a route home, they instead explore the nearby area, wandering farther and farther until they lose interest in filling that world with sand and long to move on to a new one.","ecology":"Living sandstorms are formed from and fed by the unpredictable interaction of raw elemental earth and planar storms or vortices carrying the essence of other planes. These ageless elemental creatures tend to be curious and outgoing when they first discover new places, but are easily frustrated by any kind of restraint. They use their ability to create sand liberally, attempting to pack caves, voids in the Plane of Earth, and other open areas at least half-full of their reddish sand. Because of their origin, they are usually found near gates, portals, and vortices between planes both on the Plane of Earth and on the Material Plane.","habitat_society":"Living sandstorms dwell in the rare open caverns on the Plane of Earth. On that plane, they are misfits, feared for their affinities for open spaces and howling winds. When conflicts erupt between the powers of the Elemental Planes, they are sometimes recruited to lead strike teams into other planes, as they are adventurous and enjoy discovering open spaces they can fill with their fine, red sand. They are especially valuable when establishing beachheads on planes that have little in the way of earth, because of their ability to create large amounts of sand in relatively short periods of time.\n\nDue to their intrepidness, they readily answer callings to serve summoners so they can visit new places and spread their sand far and wide. If they see an opportunity to do so, they may break free of their calling and explore the wider Material Plane, where they favor desert climes and their nearby regions, and where they are known to contribute to rapid desertification. When marooned on the Material Plane, they are generally restless until they find a way back to the Plane of Earth, but if they know of a route home, they instead explore the nearby area, wandering farther and farther until they lose interest in filling that world with sand and long to move on to a new one."},{"name":"Living Sandstorm","cr":11,"xp":12800,"alignment":"N","size":"Fine","type":"outsider","subtypes":["earth","elemental","swarm"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"sandsight"},{"type":"tremorsense","modifier":"60 ft."}],"ac":34,"ac_touch":25,"ac_flat_footed":27,"ac_mods":"+6 Dex, +1 dodge, +9 natural, +8 size","hp":147,"hd":"14d10+70","hdvalue":14,"fort":9,"ref":15,"will":12,"defensive_abilities":["swarm traits"],"dr":"10/-","immunities":["elemental traits","weapon damage"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"swarm (6d6 plus distraction)","space":"5 ft.","reach":"0 ft.","special_attacks":[{"type":"create sand"},{"type":"distraction","details":"DC 22"},{"type":"sand blast"}],"strength":1,"dexterity":22,"constitution":21,"intelligence":12,"wisdom":12,"charisma":13,"baseatk":14,"feats":[{"feat":"Dodge"},{"feat":"Improved Iron Will"},{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Step Up"}],"skills":[{"skill":"Acrobatics","value":20},{"skill":"Fly","value":35},{"skill":"Intimidate","value":18},{"skill":"Knowledge (planes)","value":18},{"skill":"Linguistics","value":4},{"skill":"Perception","value":18},{"skill":"Stealth","value":39,"special":"+47 in sand"},{"skill":"Survival","value":18}],"languages":["Aquan","Auran","Common","Ignan","Terran"],"sq":[{"type":"change shape","details":"humanoid form or sandstorm form; polymorph"}],"environments":["any deserts (Plane of Earth)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This hulking humanoid figure of packed red sand is no taller than an average human, but it is brawny and exceptionally broad.","source":"AP 83","special_abilities":[{"type":"Create Sand","kind":"Su","details":"While in sandstorm form, a living sandstorm can, as a standard action, create 500 cubic ft. of fine red sand, filling a 10-foot radius beneath it to a depth of 5 ft. All creatures in the area and adjacent squares must succeed at a DC 22 Reflex save or be blinded for 1d4 rounds. Medium and smaller creatures in the area are buried and must begin holding their breath to avoid drowning in the sand. By attempting a Reflex save against the same DC, a creature can avoid being buried if there is an adjacent space outside the area to which it can move; if the save is successful, the creature is moved into an available adjacent space. As a standard action, each buried creature can dig itself out or be dug out by another with a successful DC 15 Strength check. Invisible creatures in or adjacent to the area when the sand is created are outlined until the dust is removed. The save DC is Constitution-based."},{"type":"Sand Blast","kind":"Ex","details":"When in sandstorm form, a living sandstorm can attack with a blast of scouring sand in a 20-foot line. The sand deals 6d6 points of slashing damage and blinds creatures in the area for 1d4 rounds. A successful DC 22 Reflex save halves the damage and negates the blinding. The save DC is Constitution-based."}],"description":"Notorious for appearing suddenly out of the roiling tempests of the deep desert, living sandstorms are capable of turning oases and dry farmlands into areas of featureless desert in a shockingly short span of time. When angered, they can scour a whole army down to bits of shining metal and bone buried under ft. of shifting sand over the course of one terrible night. Some Osiriani scholars claim that living sandstorms are related to the deadly khamsin storms that scour the desert, and while these creatures are related to elementals, they have nothing to do with the formation of those iconic storms. Living sandstorms are most comfortable when sand is free to flow across the earth. They become agitated whenever creatures make an effort to remove or limit sand in an area, shelter an area from the drifting dust, or alter the weather to reduce or prevent sandstorms. However, they are curious creatures and enjoy experiencing new interactions with beings of other shapes, and are willing to parley when they believe doing so may open the door to a novel diversion-or if a creature simply appears easy to intimidate.\n\nA living sandstorm in its humanoid shape is about 6 ft. tall and weighs 900 pounds. In sandstorm form, it expands its form into a pulsing cloud of streaming, loose sand, which gathers into small clumps before being reabsorbed into the storm.\n\nEcology\n\nLiving sandstorms are formed from and fed by the unpredictable interaction of raw elemental earth and planar storms or vortices carrying the essence of other planes. These ageless elemental creatures tend to be curious and outgoing when they first discover new places, but are easily frustrated by any kind of restraint. They use their ability to create sand liberally, attempting to pack caves, voids in the Plane of Earth, and other open areas at least half-full of their reddish sand. Because of their origin, they are usually found near gates, portals, and vortices between planes both on the Plane of Earth and on the Material Plane.\n\nHabitat & Society\n\nLiving sandstorms dwell in the rare open caverns on the Plane of Earth. On that plane, they are misfits, feared for their affinities for open spaces and howling winds. When conflicts erupt between the powers of the Elemental Planes, they are sometimes recruited to lead strike teams into other planes, as they are adventurous and enjoy discovering open spaces they can fill with their fine, red sand. They are especially valuable when establishing beachheads on planes that have little in the way of earth, because of their ability to create large amounts of sand in relatively short periods of time.\n\nDue to their intrepidness, they readily answer callings to serve summoners so they can visit new places and spread their sand far and wide. If they see an opportunity to do so, they may break free of their calling and explore the wider Material Plane, where they favor desert climes and their nearby regions, and where they are known to contribute to rapid desertification. When marooned on the Material Plane, they are generally restless until they find a way back to the Plane of Earth, but if they know of a route home, they instead explore the nearby area, wandering farther and farther until they lose interest in filling that world with sand and long to move on to a new one.","ecology":"Living sandstorms are formed from and fed by the unpredictable interaction of raw elemental earth and planar storms or vortices carrying the essence of other planes. These ageless elemental creatures tend to be curious and outgoing when they first discover new places, but are easily frustrated by any kind of restraint. They use their ability to create sand liberally, attempting to pack caves, voids in the Plane of Earth, and other open areas at least half-full of their reddish sand. Because of their origin, they are usually found near gates, portals, and vortices between planes both on the Plane of Earth and on the Material Plane.","habitat_society":"Living sandstorms dwell in the rare open caverns on the Plane of Earth. On that plane, they are misfits, feared for their affinities for open spaces and howling winds. When conflicts erupt between the powers of the Elemental Planes, they are sometimes recruited to lead strike teams into other planes, as they are adventurous and enjoy discovering open spaces they can fill with their fine, red sand. They are especially valuable when establishing beachheads on planes that have little in the way of earth, because of their ability to create large amounts of sand in relatively short periods of time.\n\nDue to their intrepidness, they readily answer callings to serve summoners so they can visit new places and spread their sand far and wide. If they see an opportunity to do so, they may break free of their calling and explore the wider Material Plane, where they favor desert climes and their nearby regions, and where they are known to contribute to rapid desertification. When marooned on the Material Plane, they are generally restless until they find a way back to the Plane of Earth, but if they know of a route home, they instead explore the nearby area, wandering farther and farther until they lose interest in filling that world with sand and long to move on to a new one."},{"name":"Lukwata","cr":11,"xp":12800,"alignment":"N","size":"Huge","type":"magical beast","subtypes":["aquatic"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":25,"ac_touch":12,"ac_flat_footed":21,"ac_mods":"+4 Dex, +13 natural, -2 size","hp":147,"hd":"14d10+70","hdvalue":14,"fort":14,"ref":13,"will":8,"dr":"10/nonmagical weapons","sr":27,"weaknesses":["eldritch encrustation"],"speed":[{"type":"swim","speed":40}],"melee":"bite +22 (4d10+15/19-20 plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"capsize","details":"DC 25"},{"type":"digest magic"},{"type":"dispelling bite"}],"strength":30,"dexterity":19,"constitution":20,"intelligence":2,"wisdom":15,"charisma":11,"baseatk":14,"cmb":26,"cmb_special":"+4 vs. grapple","cmd":40,"feats":[{"feat":"Awesome Blow"},{"feat":"Bleeding Critical"},{"feat":"Critical Focus"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (bite)"},{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Perception","value":9},{"skill":"Stealth","value":0},{"skill":"Swim","value":30}],"environments":["any lakes","any swamps","warm rivers"],"organizations":["solitary","pair","school (3-8)"],"treasure":"standard","description_visual":"A long, spiny fin runs down the length of the dolphinlike body of this eel-headed predator.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Damage Reduction","kind":"Ex","details":"A lukwata's damage reduction is penetrated only by nonmagical weapons (temporary magical weapons, such as those created by the spell magic weapon and similar effects, count as magical weapons)."},{"type":"Digest Magic","kind":"Su","details":"A magic item swallowed by a lukwata must make a DC 22 Fortitude save after an hour or become permanently nonmagical. Artifacts are immune to this effect. The save DC is Constitution-based."},{"type":"Dispelling Bite","kind":"Su","details":"When a lukwata scores a critical hit with its bite, the victim is affected as if targeted by a greater dispel magic spell. The caster level for this effect is equal to the lukwata's Hit Dice (CL 14th for most lukwatas)."},{"type":"Eldritch Encrustation","kind":"Su","details":"Crystalline growths along the lukwata's digestive tract contain large deposits of magical energy. These nodes are responsible for the magical feedback that surrounds each lukwata, granting it its spell resistance, damage reduction, dispelling bite, and digest magic abilities. Dispel magic cast on a lukwata can negate these powers for 1 minute-the CL of the effect is treated as the lukwata's Hit Dice (CL 11th for most lukwatas)."}],"description":"Lukwatas slip through dark tropical waters, preying upon all who dare enter their deep jungle rivers and pools, including beasts typically considered apex predators. While scholars say the beasts favor the dark, light doesn't deter them in their relentless pursuit of prey. Their long, flat bodies are reminiscent of those of dolphins or large fish, but lukwatas' heads are distinctively eel-like. A lukwata's unusual ability to disrupt magical effects rises from the strange crystalline growths that line its throat and stomach-crystals that allow the lukwata to gain nutrients from magical items as efficiently as from flesh and blood. These same growths give the lukwata an unusually strong resistance to all manner of magic attacks.\n\nLukwatas hate crocodiles, their chief predatory rivals, and attack them on sight, even if the lukwata has recently fed. Most crocodilians are not large enough to pose a significant threat; however, some accounts exist of lukwatas and dire crocodiles crossing paths. These fights are renowned for inf licting great destruction, with the embattled creatures smashing to bits piers, flotillas, and even dams in their fury.\n\nA lukwata is 20 ft. long and weighs 4,000 pounds.","ecology":"","habitat_society":""},{"name":"Marax","cr":11,"xp":12800,"alignment":"N","size":"Large","type":"animal","init":6,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":25,"ac_touch":11,"ac_flat_footed":23,"ac_mods":"+2 Dex, +14 natural, -1 size","hp":152,"hd":"16d8+80","hdvalue":16,"fort":17,"ref":12,"will":7,"save_mods":"+2 vs. poison","speed":[{"type":"land","speed":40}],"melee":"bite +20 (2d6+9/19-20), 2 talons +20 (1d8+9), tail barbs +18 (1d6+4 plus poison)","space":"10 ft.","reach":"10 ft. (5 ft. with talons)","special_attacks":[{"type":"poison"},{"type":"pounce"}],"strength":28,"dexterity":15,"constitution":21,"intelligence":2,"wisdom":15,"charisma":6,"baseatk":12,"cmb":22,"cmd":34,"feats":[{"feat":"Bleeding Critical"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Multiattack"}],"skills":[{"skill":"Perception","value":20},{"skill":"Stealth","value":10}],"environments":["warm forests","warm plains"],"organizations":["solitary","pair","pack (3-12)"],"treasure":"none","description_visual":"Dense, bony growths line the back of this bipedal predator. Between its gnashing, toothy underbite, scythe-like claws, and spiked tail, no part of this beast offers mercy.","source":"AP 90","special_abilities":[{"type":"Poison","kind":"Ex","details":"Tail barbs-injury; save Fort DC 23; frequency 1/round for 6 rounds; effect 1d4 Dex; cure 2 consecutive saves. Cunning and brutal, maraxes are far-ranging predators from Castrovel's mist-shrouded landscape. Gifted with vicious weapons, dense armor, and a paralytic venom, a single marax is a match for even the greatest hunter. A pack can easily bring down Castrovel's largest creatures and defend their territory against the planet's most fearsome competitors. Variations of maraxes dot Castrovel's different regions just as big cats stalk Golarion's. Different subspecies can be identified by their varying fur colors and patterns and the arrangement of ridges on their dorsal plates. Maraxes typically stand 9 to 10 ft. tall and weigh up to 900 pounds. Ecology While they are far from the most dangerous predators on their homeworld, maraxes stand among the planet's more successful hunters thanks to their inherent adaptability. Perfectly suited to the forests and plains of Castrovel, they roam enormous territories as lone hunters or in small packs."}],"description":"Their seasonal migrations create famine in their wakes as they drain a region of fauna, and entire lashunta villages may relocate seasonally to avoid starvation. Maraxes possess only a single lung, and those introduced to alien environments often become extremely irritable due to shortness of breath.\n\nMaraxes are overwhelmingly carnivorous. The larger, more aggressive females dominate their packs, bringing down prey and eating first. Maraxes have voracious appetites, and will make a meal of almost anything-in lean times the animals turn to carrion, fruit, and in rare cases even soil and stones to sate their voracious appetites.\n\nStraddling the line between mammal and reptile, maraxes are warm-blooded creatures with resilient bodies. Soft fur covers tough scales across much of a marax's body, while bony knobs protect the head, back, thighs, and tail. A marax's most identifiable feature is its tough dorsal osteoderms that offer protection. They lack forelimbs, and balance instead on a single pair of legs tipped with vicious, scythe-like claws. Their oversized jaws can crush both bone and stone, and larger specimens can even tear through metal armor. A cluster of venomous barbs sprout from the end of a marax's tail, which can inject enough paralytic venom to bring down prey twice the creature's size.\n\nThese statistics represent a typical marax. Various subspecies may be larger or smaller (use the giant creature or young creature simple templates accordingly) and possess a variety of different special abilities. The arctic-dwelling tundrax is smaller, but can hibernate for months beneath the snow and reawaken in moments to pounce upon unsuspecting prey, while females of the bioluminescent ghostback marax possess a resin-producing gland that grants them an ability similar to the web special ability.\n\nHabitat & Society\n\nMaraxes are found all across Castrovel, but exist primarily in its primeval forests and vast savannas. Dozens of subspecies fill the planet's various ecological niches, and maraxes range from the polar tundra to steaming tropical jungles. Thanks to Castrovel's dramatic tides and powerful weather systems, regular migration is a way of life, and packs can cover hundreds of miles between seasonal hunting grounds. Some subspecies follow staple herds, while others alternate between a variety of environments and diets throughout the year. Most maraxes spend dry seasons stalking small prey in wooded areas or deep in Castrovel's countless hidden valleys, then during wet seasons move onto open savanna to take down larger prey. Wherever they settle for a time, packs use their powerful claws to dig out shallow nests, which shelter a complex Ecology of scavengers and opportunistic mammals once the beasts move on.\n\nMost breeds of maraxes are social animals that form complex hierarchies. They vocalize a variety of chirps,\n\ngrowls, and rasping grunts, and establish relative status with bellowing exchanges that lashunta call \"debates.\" The largest female typically leads the pack, and surrounds herself with the other breeding-age females for hunting and territorial defense. Males and females not of breeding age rely on this matriarch's circle for food, and are expected to groom the hunters and one another for parasites. All members of a pack contribute to marking and defending territory and to scavenging during lean times. The social bonds are knit tight, and packs are more likely to move on to new hunting grounds than drive out members in hard times. An alpha female remains fertile so long as she is well fed, and especially successful matriarchs can grow to enormous sizes and dominate packs of fifty or more, cultivating legends and nicknames among lashunta hunters.\n\nNon-alpha females breed only two or three litters in a lifetime. Females attract the attention of males using their tail barbs, and engage other females in mock combat to claim the healthiest mates. If a male shows interest, the female bonds her clutch of two to four eggs to his underbelly with a sticky resin. The father becomes incubator and guardian for the next 16 months. Hatchlings are born with soft, flexible back plates, and adults claw and nip at a pup's back to transform the soft cartilage into thick, sturdy osteoderms. The venom both males and females produce in their tails is a complex array of proteins and enzymes that the hatchlings suckle for nourishment during their vulnerable first few days. As one would expect, maraxes are very protective parents; packs will chase kidnappers for miles and tear them apart with an almost gleeful cruelty.\n\nThanks to Castrovel's numerous planetary portals, maraxes occasionally migrate to other worlds. A smaller, wheezing variety prowls Akiton's equator, riding the planet's massive dust storms from hunting ground to hunting ground. On Golarion, a few small packs roam Numeria and southern Garund, preying on the megafauna in these locations.\n\nAmong Castrovel's civilizations, capturing or slaying a marax is an impressive achievement. As maraxes' natural weapons can be used to craft vicious daggers, spears, and terbutje, those capable of reliably trapping or hunting the creatures earn impressive fortunes and high prestige.\n\nNear rural settlements, maraxes stalk domesticated herds for easy meals, and even pick off careless hunters and shepherds without fear. Their hunting tactics are so effective that some lashunta have bred a loyal domesticated subspecies to guard their wilderness settlements from predation. Though ravenous and ill tempered, these tame maraxes are unf laggingly loyal. Druidic sects see the creature as a powerful totem, crafting fetishes from the animal's bones and plates and divining prophecies from packs' seasonal migrations.","ecology":"of scavengers and opportunistic mammals once the beasts move on.\n\nMost breeds of maraxes are social animals that form complex hierarchies. They vocalize a variety of chirps,\n\ngrowls, and rasping grunts, and establish relative status with bellowing exchanges that lashunta call \"debates.\" The largest female typically leads the pack, and surrounds herself with the other breeding-age females for hunting and territorial defense. Males and females not of breeding age rely on this matriarch's circle for food, and are expected to groom the hunters and one another for parasites. All members of a pack contribute to marking and defending territory and to scavenging during lean times. The social bonds are knit tight, and packs are more likely to move on to new hunting grounds than drive out members in hard times. An alpha female remains fertile so long as she is well fed, and especially successful matriarchs can grow to enormous sizes and dominate packs of fifty or more, cultivating legends and nicknames among lashunta hunters.\n\nNon-alpha females breed only two or three litters in a lifetime. Females attract the attention of males using their tail barbs, and engage other females in mock combat to claim the healthiest mates. If a male shows interest, the female bonds her clutch of two to four eggs to his underbelly with a sticky resin. The father becomes incubator and guardian for the next 16 months. Hatchlings are born with soft, flexible back plates, and adults claw and nip at a pup's back to transform the soft cartilage into thick, sturdy osteoderms. The venom both males and females produce in their tails is a complex array of proteins and enzymes that the hatchlings suckle for nourishment during their vulnerable first few days. As one would expect, maraxes are very protective parents; packs will chase kidnappers for miles and tear them apart with an almost gleeful cruelty.\n\nThanks to Castrovel's numerous planetary portals, maraxes occasionally migrate to other worlds. A smaller, wheezing variety prowls Akiton's equator, riding the planet's massive dust storms from hunting ground to hunting ground. On Golarion, a few small packs roam Numeria and southern Garund, preying on the megafauna in these locations.\n\nAmong Castrovel's civilizations, capturing or slaying a marax is an impressive achievement. As maraxes' natural weapons can be used to craft vicious daggers, spears, and terbutje, those capable of reliably trapping or hunting the creatures earn impressive fortunes and high prestige.\n\nNear rural settlements, maraxes stalk domesticated herds for easy meals, and even pick off careless hunters and shepherds without fear. Their hunting tactics are so effective that some lashunta have bred a loyal domesticated subspecies to guard their wilderness settlements from predation. Though ravenous and ill tempered, these tame maraxes are unf laggingly loyal. Druidic sects see the creature as a powerful totem, crafting fetishes from the animal's bones and plates and divining prophecies from packs' seasonal migrations.","habitat_society":"Maraxes are found all across Castrovel, but exist primarily in its primeval forests and vast savannas. Dozens of subspecies fill the planet's various ecological niches, and maraxes range from the polar tundra to steaming tropical jungles. Thanks to Castrovel's dramatic tides and powerful weather systems, regular migration is a way of life, and packs can cover hundreds of miles between seasonal hunting grounds. Some subspecies follow staple herds, while others alternate between a variety of environments and diets throughout the year. Most maraxes spend dry seasons stalking small prey in wooded areas or deep in Castrovel's countless hidden valleys, then during wet seasons move onto open savanna to take down larger prey. Wherever they settle for a time, packs use their powerful claws to dig out shallow nests, which shelter a complex"},{"name":"Mature Adult White Dragon","cr":11,"xp":12800,"alignment":"CE","size":"Large","type":"dragon","subtypes":["cold"],"init":5,"senses":[{"type":"dragon senses"},{"type":"snow vision"}],"auras":["cold (5 ft., 1d6 cold damage)","frightful presence (210 ft., DC 18)"],"ac":30,"ac_touch":10,"ac_flat_footed":29,"ac_mods":"+1 Dex, +20 natural, -1 size","hp":172,"hd":"15d12+75","hdvalue":15,"fort":14,"ref":12,"will":11,"dr":"10/magic","immunities":["cold","paralysis","sleep"],"sr":22,"weaknesses":["Vulnerability to fire"],"speed":[{"type":"land","speed":30},{"type":"burrow","speed":30},{"type":"fly","speed":200,"maneuverability":"poor"},{"type":"swim","speed":60}],"melee":"bite +23 (2d6+12/19-20), 2 claws +22 (1d8+8), 2 wings +17 (1d6+4), tail slap +17 (1d8+12)","space":"10 ft.","reach":"5 ft. (10 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"40-ft. cone, DC 22, 14d4 cold"}],"spell_like_abilities_caster_level":15,"spell_like_abilities_concentration":20,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"fog cloud"},{"spell":"gust of wind"}]}],"spellsknown_caster_level":3,"spellsknown_concentration":8,"spellsknown":[{"spell_level":1,"spell_slots":6,"spells":[{"spell":"magic aura"},{"spell":"shield"},{"spell":"true strike"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mending"},{"spell":"ray of frost"}]}],"strength":27,"dexterity":12,"constitution":21,"intelligence":12,"wisdom":15,"charisma":12,"baseatk":15,"cmb":24,"cmd":35,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Flyby Attack"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Fly","value":13},{"skill":"Intimidate","value":19},{"skill":"Knowledge (arcana)","value":19},{"skill":"Perception","value":24},{"skill":"Spellcraft","value":19},{"skill":"Stealth","value":15},{"skill":"Swim","value":34}],"languages":["Common","Draconic"],"sq":[{"type":"icewalking"},{"type":"ice shape"}],"environments":["cold mountains"],"organizations":["solitary"],"treasure":"triple","description_visual":"This dragon's scales are a frosty white. Its head is crowned with slender horns, with a thin membrane stretched between them.","group":"Chromatic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Ice Shape","kind":"Su","details":"A young white dragon can shape ice and snow at will. This ability functions as stone shape, but only targeting ice and snow, not stone. A white dragon's caster level for this effect is equal to its Hit Dice."},{"type":"Icewalking","kind":"Ex","details":"This ability works like the spider climb spell, but the surfaces the dragon climbs must be icy. The dragon can move across icy surfaces without penalty and doesn't need to make Acrobatics checks to run or charge on ice."},{"type":"Snow Vision","kind":"Ex","details":"A very young white dragon learns to see perfectly well in snowy conditions. A white dragon doesn't suffer any penalties to Perception checks while in snow."}],"description":"Although most consider it to be the weakest and most feral of the chromatic dragons, the white dragon makes up for its lack of cunning with sheer ferocity. White dragons dwell on remote, frozen mountaintops and in arctic lowlands, making their home in glittering caves full of ice and snow. They prefer their meals completely frozen.","ecology":"","habitat_society":""},{"name":"Meladaemon","cr":11,"xp":12800,"alignment":"NE","size":"Large","type":"outsider","subtypes":["daemon","evil","extraplanar"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect magic"}],"auras":["consumptive aura (20 ft.)"],"ac":25,"ac_touch":15,"ac_flat_footed":19,"ac_mods":"+6 Dex, +10 natural, -1 size","hp":147,"hd":"14d10+70","hdvalue":14,"fort":11,"ref":15,"will":14,"dr":"10/good","immunities":["acid","critical hits","death effects","disease","poison","sneak attack"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":22,"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"bite +20 (2d8+6/19-20 plus disease), 2 claws +19 (2d6+6 plus hunger)","space":"10 ft.","reach":"10 ft.","spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":16,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect magic"},{"spell":"see invisibility"}]},{"frequency":"at-will","spells":[{"spell":"cause fear"},{"spell":"deeper darkness"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"}]},{"frequency":"1/day","spells":[{"spell":"horrid wilting"},{"spell":"waves of fatigue"}]},{"frequency":"3/day","spells":[{"spell":"blight"},{"spell":"diminish plants"},{"spell":"quickened magic missile"}]}],"strength":22,"dexterity":22,"constitution":21,"intelligence":21,"wisdom":17,"charisma":18,"baseatk":14,"cmb":21,"cmd":37,"feats":[{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (bite)"},{"feat":"Iron Will"},{"feat":"Quicken Spell-Like Ability (magic missile)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Bluff","value":21},{"skill":"Fly","value":17},{"skill":"Heal","value":11},{"skill":"Intimidate","value":21},{"skill":"Knowledge (planes)","value":22},{"skill":"Knowledge (religion)","value":22},{"skill":"Perception","value":20},{"skill":"Sense Motive","value":20},{"skill":"Spellcraft","value":22},{"skill":"Stealth","value":19},{"skill":"Survival","value":20},{"skill":"Use Magic Device","value":14}],"languages":["Abyssal","Draconic","Infernal","telepathy 100 ft."],"environments":["any (Abaddon)"],"organizations":["solitary","pack (2-5)","cabal (6-12)"],"treasure":"standard","description_visual":"This foul creature looks like an emaciated humanoid with the head of a jackal.","group":"Daemon","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Consumptive Aura","kind":"Su","details":"A meladaemon radiates an aura of hunger to a radius of 20 ft. Every round a creature begins its turn within this aura, it must succeed at a DC 22 Fortitude save or take 1d6 nonlethal damage and become fatigued from extreme hunger. Creatures that don't need to eat are immune to this effect. The save DC is Constitution-based."},{"type":"Disease","kind":"Ex","details":"Daemonic wasting: Bite-injury; save Fort DC 22; onset 1 day; frequency 1/day; effect 1d4 Con and 1d4 Cha damage; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Hunger","kind":"Su","details":"A meladaemon's claw attack deals an additional 1d6 points of nonlethal damage as it causes sudden pangs of horrific hunger in its foe. Creatures that don't need to eat are immune to this effect."}],"description":"As personifications of death from starvation and thirst, these withered fiends spend their time destroying resources and spreading hunger. Deacons of the Horseman of Famine, these creatures visit worlds throughout the planes, destroying acres of crops and slaughtering livestock in order to harvest souls for their honored master. Meladaemons delight in the slow death of starvation, going so far as to experiment with various bodily deficiencies and mortal weaknesses. Arrogant and utterly bound to their patron, meladaemons rarely work with others of their kind and never serve any of the other three Horsemen except in the rarest of circumstances.\n\nMeladaemons stand approximately 12 ft. tall and weigh 350 pounds.","ecology":"","habitat_society":""}];
